module 	UART2(
	input  wire	     ipClk,
	input  wire		 ipReset,
	input  wire[7:0]ipTxData,
	input  wire		 ipTxSend,
	output reg 	     opTxBusy,
	output reg       opTx,
	input  wire      ipRx,
	output reg [7:0]opRxData,
	output reg		 opRxValid
);
reg [1:0]TxState;
	reg [1:0]RxState;
	reg [11:0]TxBdCount;
	reg [11:0]RxBdCount;
	reg [7:0]RxData;
	always @(posedge ipClk or posedge ipReset) begin
		if(ipReset) begin
			TxState <= 2'b00;
			TxBdCount <= 12'd0;
			opTxBusy <= 1'b0;
			opTx <= 1'b0;
			RxState <= 2'b00;
			RxBdCount <= 12'd0;
			opRxData <= 8'd0;
			opRxValid <= 1'b0;
		end
		else begin
			case(TxState)
				2'b00: begin
					if(ipTxSend) begin
						TxState <= 2'b01;
						TxBdCount <= 12'd0;
						opTxBusy <= 1'b1;
						opTx <= 1'b0;
					end
				end
				2'b01: begin
					if(TxBdCount == 12'd433) begin
						TxBdCount <= 12'd0;
						TxState <= 2'b10;
						opTx <= ipTxData[7];
					end
					else begin
						TxBdCount <= TxBdCount + 1'b1;
					end
				end
				2'b10: begin
					if(TxBdCount == 12'd433) begin
						TxBdCount <= 12'd0;
						TxState <= 2'b11;
						opTx <= ipTxData[6];
					end
					else begin
						TxBdCount <= TxBdCount + 1'b1;
					end
				end
				2'b11: begin
					if(TxBdCount == 12'd433) begin
						TxBdCount <= 12'd0;
						TxState <= 2'b00;
						opTx <= ipTxData[5];
						opTxBusy <= 1'b0;
					end
					else begin
						TxBdCount <= TxBdCount + 1'b1;
					end
				end
			endcase
			case(RxState)
				2'b00: begin
					if(ipRx == 1'b0) begin
						RxState <= 2'b01;
						RxBdCount <= 12'd0;
						RxData <= 8'd0;
					end
				end
				2'b01: begin
					if(RxBdCount == 12'd433) begin
						RxBdCount <= 12'd0;
						RxState <= 2'b10;
						RxData <= {RxData[6:0],ipRx};
					end
					else begin
						RxBdCount <= RxBdCount + 1'b1;
					end
				end
				2'b10: begin
					if(RxBdCount == 12'd433) begin
						RxBdCount <= 12'd0;
						RxState <= 2'b11;
						RxData <= {RxData[5:0],ipRx};
					end
					else begin
						RxBdCount <= RxBdCount + 1'b1;
					end
				end
				2'b11: begin
					if(RxBdCount == 12'd433) begin
						RxBdCount <= 12'd0;
						RxState <= 2'b00;
						opRxData <= RxData;
						opRxValid <= 1'b1;
					end
					else begin
						RxBdCount <= RxBdCount + 1'b1;
					end
				end
			endcase
		end
	end
endmodule

