    assign keypress_array[8] = 10'h01;
    assign keypress_array[9] = 10'h02;
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            counter <= 0;
            index <= 0;
            keypress <= 0;
        end
        else begin
            if (counter == 20) begin
                keypress <= keypress_array[index];
                counter <= 0;
                index <= index + 1;
            end
            else begin
                counter <= counter + 1;
            end
        end
    end
endmodule

