module vga_ctrl(
input wire pixel_clk,
output wire hsync,
output wire vsync,
output wire [9:0] pixel_x,
output wire [9:0] pixel_y,
output wire visible_region
); 

parameter [31:0] total_pixels=10000000;
parameter [31:0] h_sync_pulse=96;
parameter [31:0] h_back_porch=48;
parameter [31:0] h_front_porch=48;
parameter [31:0] v_sync_pulse=2;
parameter [31:0] v_back_porch=33;
parameter [31:0] v_front_porch=10;
parameter [31:0] h_res=640;
parameter [31:0] v_res=480;
reg [31:0] h_counter = 0;
reg [31:0] v_counter = 0;
wire [31:0] h_max = h_res + h_sync_pulse + h_back_porch + h_front_porch;
wire [31:0] v_max = v_res + v_sync_pulse + v_back_porch + v_front_porch;
  always @(posedge pixel_clk) begin
    if((h_counter == (h_max - 1))) begin
      h_counter <= 0;
      if((v_counter == (v_max - 1))) begin
        v_counter <= 0;
      end
      else begin
        v_counter <= v_counter + 1;
      end
    end
    else begin
      h_counter <= h_counter + 1;
    end
  end
  assign hsync = h_counter >= (h_res + h_sync_pulse) ? 1'b1 : 1'b0;
  assign vsync = v_counter >= (v_res + v_sync_pulse) ? 1'b1 : 1'b0;
  assign pixel_x = h_counter;
  assign pixel_y = v_counter;
  assign visible_region = h_counter < h_res && v_counter < v_res ? 1'b1 : 1'b0;
endmodule

