module tone(
    input CLK,
    input[31:0] period, 
    output reg tone_out
    );
parameter CLK_F = 32; 

reg[31:0] prescaler = 0;
reg[31:0] counter = 0;

always @(posedge CLK) begin
    prescaler <= prescaler + 1;
    if (prescaler == CLK_F) begin
        prescaler <= 0;
        counter <= counter + 1;
        if (counter == period) begin
            counter <= 0;
            tone_out <= ~tone_out;
        end
    end
end

endmodule

