    reg [7:0] rx_shift_reg;
    reg [3:0] rx_counter;
    reg rx_sample;
    reg rx_vld_int;
    reg rx_frame_error_int;

    assign uart_tx = tx_shift_reg[7];
    assign rx_data = rx_shift_reg;
    assign rx_vld = rx_vld_int;
    assign rx_frame_error = rx_frame_error_int;

    always @(posedge clk_50) begin
        if (tx_vld) begin
            tx_shift_reg <= {tx_data, 1'b0};
            tx_counter <= 4'd0;
            tx_busy <= 1'b1;
        end
        else if (tx_busy) begin
            tx_shift_reg <= {tx_shift_reg[6:0], 1'b0};
            tx_counter <= tx_counter + 4'd1;
            if (tx_counter == 4'd7) begin
                tx_busy <= 1'b0;
            end
        end
    end

    always @(posedge clk_50) begin
        rx_counter <= rx_counter + 4'd1;
        if (rx_counter == 4'd0) begin
            rx_sample <= uart_rx;
        end
        if (rx_counter == SAMPLE_CLK_DIV) begin
            rx_shift_reg <= {rx_shift_reg[6:0], rx_sample};
            rx_counter <= 4'd0;
        end
    end

    always @(posedge clk_50) begin
        if (rx_counter == SAMPLE_CLK_DIV) begin
            rx_vld_int <= 1'b1;
            rx_frame_error_int <= 1'b0;
            if (rx_shift_reg[7:0] != 8'h00) begin
                rx_frame_error_int <= 1'b1;
            end
        end
        else begin
            rx_vld_int <= 1'b0;
        end
    end

endmodule

