module clk_div(
input wire clk_i,
output reg clk_o,
output wire [1:0] count_o
); 

reg [1:0] counter = 1'b0;
  always @(posedge clk_i) begin
    if(counter == 2'b11) begin
      counter <= 2'b00;
    end
    else begin
      counter <= counter + 1;
    end
  end
  assign count_o = counter;
  always @(posedge clk_i) begin
    if(counter == 2'b00) begin
      clk_o <= 1'b0;
    end
    else if(counter == 2'b01) begin
      clk_o <= 1'b1;
    end
    else if(counter == 2'b10) begin
      clk_o <= 1'b1;
    end
    else begin
      clk_o <= 1'b0;
    end
  end
endmodule

module hardcopyiv_hssi_aux_clock_div (
    clk,     
    reset,   
    enable_d, 
    d,        
    clkout   
);
input clk,reset;
input enable_d;
input [7:0] d;
output clkout;
parameter clk_divide_by = 1;
parameter extra_latency = 0;

reg clk_last_value;
reg [31:0] count;
reg [31:0] count_last_value;
reg [31:0] clk_divide_by_int;
reg [31:0] extra_latency_int;
reg clkout_tmp;
wire clk_divide_by_wire;

assign clk_divide_by_wire = (clk_divide_by == 1) ? 1'b0 : 1'b1;

always @ (clk or reset)
begin
    if (reset == 1'b1)
    begin
        clk_last_value = 1'b0;
        count = 0;
        count_last_value = 0;
        clk_divide_by_int = clk_divide_by_wire;
        extra_latency_int = extra_latency;
        clkout_tmp = 1'b0;
    end
    else
    begin
        clk_last_value = clk;
        if (enable_d == 1'b1)
        begin
            if (clk_last_value == 1'b0 && clk == 1'b1)
            begin
                count = count + 1;
                if (count == (clk_divide_by_int - 1))
                begin
                    clkout_tmp = ~clkout_tmp;
                    count = 0;
                end
            end
        end
        if (clk_divide_by_wire != clk_divide_by_int)
        begin
            count = 0;
            clk_divide_by_int = clk_divide_by_wire;
        end
        if (extra_latency_int != extra_latency)
        begin
            count = 0;
            extra_latency_int = extra_latency;
        end
    end
end

assign clkout = clkout_tmp;

endmodule

