module fifo36_demux
  #(parameter match_data = 0,
    parameter match_mask = 0)
   (input clk, input reset, input clear,
    input [35:0] data_i, input src_rdy_i, output dst_rdy_o,
    output [35:0] data0_o, output src0_rdy_o, input dst0_rdy_i,
    output [35:0] data1_o, output src1_rdy_o, input dst1_rdy_i);
localparam IDLE = 2'b00;
   localparam DATA0 = 2'b01;
   localparam DATA1 = 2'b10;
   reg [1:0] state;
   wire [35:0] data;
   wire eof;
   wire match;
   wire src_rdy;
   wire dst0_rdy;
   wire dst1_rdy;
   wire src0_rdy;
   wire src1_rdy;
   assign data = data_i;
   assign eof = data[35];
   assign match = (data & match_mask) == match_data;
   assign src_rdy = src_rdy_i;
   assign dst0_rdy = dst0_rdy_i;
   assign dst1_rdy = dst1_rdy_i;
   assign src0_rdy = src0_rdy_i;
   assign src1_rdy = src1_rdy_i;
   assign dst_rdy_o = dst0_rdy | dst1_rdy;
   assign data0_o = data;
   assign data1_o = data;
   always @(posedge clk or posedge reset or posedge clear) begin
      if (reset || clear) begin
         state <= IDLE;
      end
      else begin
         case (state)
           IDLE: begin
              if (src_rdy) begin
                 if (match) begin
                    state <= DATA1;
                 end
                 else begin
                    state <= DATA0;
                 end
              end
           end
           DATA0: begin
              if (dst0_rdy) begin
                 state <= IDLE;
              end
           end
           DATA1: begin
              if (dst1_rdy) begin
                 state <= IDLE;
              end
           end
           default: begin
              state <= IDLE;
           end
         endcase
      end
   end
   always @(posedge clk or posedge reset or posedge clear) begin
      if (reset || clear) begin
         src0_rdy_i <= 1'b0;
         src1_rdy_i <= 1'b0;
      end
      else begin
         case (state)
           IDLE: begin
              src0_rdy_i <= 1'b0;
              src1_rdy_i <= 1'b0;
           end
           DATA0: begin
              src0_rdy_i <= 1'b1;
              src1_rdy_i <= 1'b0;
           end
           DATA1: begin
              src0_rdy_i <= 1'b0;
              src1_rdy_i <= 1'b1;
           end
           default: begin
              src0_rdy_i <= 1'b0;
              src1_rdy_i <= 1'b0;
           end
         endcase
      end
   end
endmodule

