module divider 
#(
    parameter WIDTH=23,
    parameter MODULO=6000000
)
(
    input input_clk,
    output output_clk
);
reg [WIDTH-1:0] counter;
    reg output_clk_reg;
    initial begin
        counter = 0;
        output_clk_reg = 0;
    end
    always @(posedge input_clk) begin
        if (counter == MODULO-1) begin
            counter <= 0;
            output_clk_reg <= ~output_clk_reg;
        end
        else begin
            counter <= counter + 1;
        end
    end
    assign output_clk = output_clk_reg;
endmodule

module sep32_cnt(
    input           clk,
    input           cen,
    input           zero,
    output reg [4:0]    cnt
    );
reg last_zero;

always @(posedge clk) begin
    last_zero <= zero;
    if (zero && !last_zero) begin
        cnt <= 1;
    end
    else if (cen) begin
        cnt <= cnt + 1;
    end
end

endmodule

module MicrosCounter(
input wire clk_6,
input wire reset,
output wire [31:0] data_out
); 

reg [2:0] prescaler = 1'b0;
reg [31:0] data = 1'b0;
  always @(posedge clk_6) begin
    prescaler <= prescaler + 1;
    if(prescaler >= 3'b010) begin
      prescaler <= {3{1'b0}};
      data <= data + 1;
    end
  end
  assign data_out = data;
endmodule

module dec2b2d(input rst, input [9:0]dig, output reg [3:0] uni, dec);
always @(rst or dig) begin
        if (rst) begin
            uni <= 4'b0000;
            dec <= 4'b0000;
        end
        else begin
            uni <= 4'b0000;
            dec <= 4'b0000;
            if (dig[9]) uni <= 4'b0001;
            else if (dig[8]) uni <= 4'b0010;
            else if (dig[7]) uni <= 4'b0011;
            else if (dig[6]) uni <= 4'b0100;
            else if (dig[5]) uni <= 4'b0101;
            else if (dig[4]) uni <= 4'b0110;
            else if (dig[3]) uni <= 4'b0111;
            else if (dig[2]) uni <= 4'b1000;
            else if (dig[1]) uni <= 4'b1001;
            else if (dig[0]) uni <= 4'b1010;
        end
    end
endmodule

