module receiver(input wire rx,
		output reg rdy,
		input wire rdy_clr,
		input wire clk_50m,rst,
		input wire clken,
		output reg [7:0] data);
reg [1:0] state;
	reg [3:0] cnt;
	reg [7:0] rx_data;
	reg rx_sample;

	always @(posedge clk_50m or negedge rst) begin
		if (!rst) begin
			state <= 0;
			cnt <= 0;
			rx_sample <= 0;
			rdy <= 0;
			data <= 0;
		end else if (clken) begin
			rx_sample <= rx;
			case (state)
				0: begin
					if (rx_sample == 0) begin
						state <= 1;
						cnt <= 0;
					end
				end
				1: begin
					if (rx_sample == 1) begin
						state <= 2;
						cnt <= 0;
					end
					else begin
						cnt <= cnt + 1;
						if (cnt == 4) begin
							rdy <= 0;
							state <= 0;
						end
					end
				end
				2: begin
					if (rx_sample == 0) begin
						cnt <= cnt + 1;
						if (cnt == 7) begin
							state <= 3;
							cnt <= 0;
						end
					end
					else begin
						cnt <= cnt + 1;
						if (cnt == 7) begin
							state <= 0;
							rdy <= 1;
							data <= rx_data;
						end
					end
				end
			endcase
		end
		if (rdy_clr) begin
			rdy <= 0;
		end
	end
endmodule

