module Counter2(
    input clk,
    input start,
    input reset,
    output reg [3:0] count1,
    output reg [3:0] count2,
    output reg done
    );
parameter mod = 9;

    always @(posedge clk or posedge reset)
    begin
        if (reset)
        begin
            count1 <= 0;
            count2 <= 0;
            done <= 0;
        end
        else if (start)
        begin
            if (count1 == mod-1)
            begin
                count1 <= 0;
                if (count2 == mod-1)
                begin
                    count2 <= 0;
                    if (count1 == mod-2)
                    begin
                        count1 <= mod-1;
                        done <= 1;
                    end
                    else
                        count1 <= count1 + 1;
                end
                else
                    count2 <= count2 + 1;
            end
            else
                count1 <= count1 + 1;
        end
        else
        begin
            done <= 0;
            count1 <= 0;
            count2 <= 0;
        end
    end
endmodule

