module UARTTransmitter(
  input        clock,
               reset,
               io_valid,
  input  [7:0] io_bits,
  input        tick,
  output       io_ready,
               tx
);
reg [3:0] state;
  reg [7:0] data;
  assign io_ready = (state == 4'h0);
  assign tx = data[0];
  always @(posedge clock) begin
    if (reset) begin
      state <= 4'h0;
      data <= 8'h0;
    end
    else begin
      if (tick) begin
        if (state == 4'h0) begin
          if (io_valid) begin
            state <= 4'h1;
            data <= io_bits;
          end
        end
        else if (state < 4'h9) begin
          state <= state + 4'h1;
          data <= data >> 1'b1;
        end
        else if (state == 4'h9) begin
          state <= 4'hA;
        end
        else if (state == 4'hA) begin
          state <= 4'hB;
        end
        else if (state == 4'hB) begin
          state <= 4'h0;
        end
      end
    end
  end
endmodule

