module CW_REGISTER(
input wire [2:0] D,
input wire [2:0] A,
input wire WR,
input wire RD,
input wire CLK,
input wire RST,
output wire WCTRL,
output reg [6:0] Y
); 

reg [2:0] data;
reg [2:0] next_data;
reg WCTRL_reg;
  always @(posedge CLK, posedge RST) begin
    if((RST == 1'b1)) begin
      data <= 3'b000;
      WCTRL_reg <= 1'b0;
    end else begin
      data <= next_data;
      WCTRL_reg <= WR;
    end
  end
  always @(data, WR, RD, D, A) begin
    if((WR == 1'b1)) begin
      next_data <= D;
    end
    else if((RD == 1'b1)) begin
      next_data <= 3'b000;
    end
    else begin
      next_data <= data;
    end
  end
  always @(data) begin
    Y <= 7'b0000000;
    Y[data] <= 1'b1;
  end
  assign WCTRL = WCTRL_reg;
endmodule

