module vga_controller(
input wire RST,
input wire CLK,
output wire H_SYNC,
output wire V_SYNC,
output wire [10:0] X,
output wire [10:0] Y,
output wire DISP_EN
); 

parameter [31:0] H_ACTIVE=1280;
parameter [31:0] V_ACTIVE=720;
parameter [31:0] H_FRONT_PORCH=16;
parameter [31:0] V_FRONT_PORCH=10;
parameter [31:0] H_SYNC_PULSE=96;
parameter [31:0] V_SYNC_PULSE=2;
parameter [31:0] H_BACK_PORCH=48;
parameter [31:0] V_BACK_PORCH=33;
parameter [31:0] H_PIXELS=1360;
parameter [31:0] V_LINES=753;
reg [10:0] x_reg = 1'b0;
reg [10:0] y_reg = 1'b0;
reg h_sync_reg = 1'b0;
reg v_sync_reg = 1'b0;
reg disp_en_reg = 1'b0;
  always @(posedge CLK, posedge RST) begin
    if((RST == 1'b1)) begin
      x_reg <= {11{1'b0}};
      y_reg <= {11{1'b0}};
      h_sync_reg <= 1'b0;
      v_sync_reg <= 1'b0;
      disp_en_reg <= 1'b0;
    end else begin
      if((x_reg < (H_PIXELS - 1))) begin
        x_reg <= x_reg + 1;
        disp_en_reg <= 1'b1;
        if((x_reg >= (H_ACTIVE + H_FRONT_PORCH + H_SYNC_PULSE))) begin
          h_sync_reg <= 1'b1;
        end
        if((x_reg >= (H_ACTIVE + H_FRONT_PORCH + H_SYNC_PULSE + H_BACK_PORCH))) begin
          disp_en_reg <= 1'b0;
        end
      end
      else begin
        x_reg <= {11{1'b0}};
        if((y_reg < (V_LINES - 1))) begin
          y_reg <= y_reg + 1;
          if((y_reg >= (V_ACTIVE + V_FRONT_PORCH + V_SYNC_PULSE))) begin
            v_sync_reg <= 1'b1;
          end
          if((y_reg >= (V_ACTIVE + V_FRONT_PORCH + V_SYNC_PULSE + V_BACK_PORCH))) begin
            v_sync_reg <= 1'b0;
          end
        end
        else begin
          y_reg <= {11{1'b0}};
        end
      end
    end
  end
  assign H_SYNC = h_sync_reg;
  assign V_SYNC = v_sync_reg;
  assign X = x_reg;
  assign Y = y_reg;
  assign DISP_EN = disp_en_reg;
endmodule

