module rbw_check(
    input wire          clk,        
    input wire          a_rst,      
    input wire          i_rbw,      
    input wire[L:0]     i_rbw_adr,  
    input wire          rs,         
    input wire          r_ts,       
    input wire[L:0]     rs_adr,     
    input wire          ws,         
    input wire          w_ts,       
    input wire[L:0]     ws_adr,     
    output wire         o_rbw       
);
localparam L = 12;

reg rbw;
reg[L:0] rbw_adr;
reg r_ts_reg;

always @(posedge clk or posedge a_rst) begin
    if (a_rst) begin
        rbw <= 1'b0;
        rbw_adr <= {L{1'b0}};
        r_ts_reg <= 1'b0;
    end
    else begin
        rbw <= i_rbw;
        rbw_adr <= i_rbw_adr;
        r_ts_reg <= r_ts;
    end
end

wire rbw_invalid = ws && (ws_adr == rbw_adr) && (w_ts == r_ts_reg);

assign o_rbw = rbw && !rbw_invalid;

endmodule

