module ps2controller (
    input reset,
    input i_clock,
    input i_data,
    output scan_ready,
    output [7:0] scan_code
);
reg [7:0] scan_code_reg;
    reg [3:0] counter;
    reg ready;

    always @(negedge i_clock or posedge reset) begin
        if (reset) begin
            scan_code_reg <= 8'b0;
            counter <= 4'b0;
            ready <= 1'b0;
        end
        else begin
            if (counter < 4'd8) begin
                scan_code_reg[counter] <= i_data;
                counter <= counter + 4'b1;
            end
            else if (counter == 4'd9) begin
                ready <= scan_code_reg[7:0] ^ scan_code_reg[8];
            end
            else if (counter == 4'd10) begin
                ready <= ready & ~i_data;
                counter <= 4'b0;
            end
        end
    end

    assign scan_ready = ready;
    assign scan_code = scan_code_reg;

endmodule

