module radix2(
		input wire [1:0] state,
		input wire signed [23:0] din_a_r,
		input wire signed [23:0] din_a_i,
		input wire signed [23:0] din_b_r,
		input wire signed [23:0] din_b_i,
		input wire signed [23:0] w_r,
		input wire signed [23:0] w_i,
		output reg signed[23:0] op_r,
		output reg signed[23:0] op_i,
		output reg signed[23:0] delay_r,
		output reg signed[23:0] delay_i,
		output reg outvalid
	);
reg signed [41:0] a_r;
	reg signed [41:0] a_i;
	reg signed [41:0] b_r;
	reg signed [41:0] b_i;
	reg signed [41:0] w_r_int;
	reg signed [41:0] w_i_int;
	reg signed [41:0] op_r_int;
	reg signed [41:0] op_i_int;
	reg signed [41:0] delay_r_int;
	reg signed [41:0] delay_i_int;

	always @(*) begin
		case(state)
			2'b00: begin
				outvalid = 1'b0;
				op_r_int = 0;
				op_i_int = 0;
				delay_r_int = 0;
				delay_i_int = 0;
			end
			2'b01: begin
				outvalid = 1'b1;
				op_r_int = din_a_r + din_b_r;
				op_i_int = din_a_i + din_b_i;
				delay_r_int = din_a_r - din_b_r;
				delay_i_int = din_a_i - din_b_i;
			end
			2'b10: begin
				outvalid = 1'b1;
				w_r_int = w_r;
				w_i_int = w_i;
				op_r_int = delay_r_int * w_r_int;
				op_i_int = delay_i_int * w_i_int;
				delay_r_int = op_r_int - op_i_int;
				delay_i_int = op_r_int + op_i_int;
			end
			2'b11: begin
				outvalid = 1'b0;
				op_r_int = 0;
				op_i_int = 0;
				delay_r_int = 0;
				delay_i_int = 0;
			end
		endcase
	end

	always @(*) begin
		op_r = op_r_int;
		op_i = op_i_int;
		delay_r = delay_r_int;
		delay_i = delay_i_int;
	end

endmodule

module AMSG_kirsch_e(
