    wire [8:0] n1, n2, n3, n4, n5, n6, n7, n8, n9, n10, n11, n12, n13, n14, n15;
    wire [15:0] m1, m2, m3, m4, m5, m6, m7, m8, m9, m10, m11, m12, m13, m14, m15;
    assign n1 = p1 + p2;
    assign n2 = p3 + p4;
    assign n3 = n1 + n2;
    assign n4 = n3 + p6;
    assign n5 = p7 + p8;
    assign n6 = n5 + p9;
    assign n7 = n4 + n6;
    assign n8 = n7 + n2;
    assign n9 = n8 + n6;
    assign n10 = n9 + n1;
    assign n11 = n10 + n3;
    assign n12 = n11 + n4;
    assign n13 = n12 + n5;
    assign n14 = n13 + n7;
    assign n15 = n14 + n8;
    assign m1 = 3 * n15;
    assign m2 = 2 * n12;
    assign m3 = 2 * n10;
    assign m4 = 2 * n8;
    assign m5 = 2 * n6;
    assign m6 = 2 * n4;
    assign m7 = 2 * n2;
    assign m8 = 2 * n1;
    assign m9 = 2 * n15;
    assign m10 = 2 * n14;
    assign m11 = 2 * n13;
    assign m12 = 2 * n12;
