    input   wire            EN;
    input   wire    [31:0]  Di;
    output  wire     [31:0]  Do;
    input   wire    [11:0]   A;
reg     [31:0]  r_A;
    reg     [31:0]  Temp_D;
    reg     [31:0]  r_M [11:0];
    assign Do = (EN) ? r_M[r_A] : 32'h00000000;
    always @(posedge CLK)
