module mult_a_signed_b_signed
#(
	parameter	A_WIDTH		= 3,
	parameter	B_WIDTH		= 3,
	parameter	Q_WIDTH		= A_WIDTH+B_WIDTH,
	parameter	LATENCY		= 1
)
(
	input	arst,
	input	clk,

	input signed	[A_WIDTH-1:0]	a,
	input signed	[B_WIDTH-1:0]	b,
	output signed	[Q_WIDTH-1:0]	o
);
reg signed	[A_WIDTH-1:0]	r_a_1P;
reg signed	[B_WIDTH-1:0]	r_b_1P;
reg signed	[Q_WIDTH-1:0]	r_q_P [LATENCY-1:0];

wire signed	[Q_WIDTH-1:0]	w_q_comb;

assign	w_q_comb	= r_a_1P * r_b_1P;

always @(posedge clk or negedge arst)
begin
	if (!arst)
	begin
		r_a_1P	<=	{A_WIDTH{1'b0}};
		r_b_1P	<=	{B_WIDTH{1'b0}};
		r_q_P	<=	{LATENCY{Q_WIDTH{1'b0}}};
	end
	else
	begin
		r_a_1P	<=	a;
		r_b_1P	<=	b;
		r_q_P[0]	<=	w_q_comb;
		if (LATENCY > 1)
		begin
			r_q_P[1:0]	<=	r_q_P[0:0];
			if (LATENCY > 2)
			begin
				r_q_P[2:1]	<=	r_q_P[1:0];
				if (LATENCY > 3)
				begin
					r_q_P[3:2]	<=	r_q_P[2:1];
					if (LATENCY > 4)
					begin
						r_q_P[4:3]	<=	r_q_P[3:2];
						if (LATENCY > 5)
						begin
							r_q_P[5:4]	<=	r_q_P[4:3];
							if (LATENCY > 6)
							begin
								r_q_P[6:5]	<=	r_q_P[5:4];
								if (LATENCY > 7)
								begin
									r_q_P[7:6]	<=	r_q_P[6:5];
									if (LATENCY > 8)
									begin
										r_q_P[8:7]	<=	r_q_P[7:6];
										if (LATENCY > 9)
										begin
											r_q_P[9:8]	<=	r_q_P[8:7];
											if (LATENCY > 10)
											begin
												r_q_P[10:9]	<=	r_q_P[9:8];
											end
										end
									end
								end
							end
						end
					end
				end
			end
		end
	end
end

assign	o	= r_q_P[LATENCY-1];

endmodule

