module QueueCompatibility_14( 
  input        clock, 
  input        reset, 
  output       io_enq_ready, 
  input        io_enq_valid, 
  input  [3:0] io_enq_bits_tl_state_size, 
  input  [1:0] io_enq_bits_tl_state_source, 
  input        io_deq_ready, 
  output       io_deq_valid, 
  output [3:0] io_deq_bits_tl_state_size, 
  output [1:0] io_deq_bits_tl_state_source 
);
wire  do_enq; 
  wire  do_deq; 
  reg  maybe_full; 
  assign do_enq = io_enq_ready & io_enq_valid; 
  assign do_deq = io_deq_ready & io_deq_valid; 
  assign io_enq_ready = 1'h1; 
  assign io_deq_valid = maybe_full; 
  assign io_deq_bits_tl_state_size = io_enq_bits_tl_state_size; 
  assign io_deq_bits_tl_state_source = io_enq_bits_tl_state_source; 
  always @(posedge clock) begin 
    if (reset) begin 
      maybe_full <= 1'h0; 
    end else begin 
      maybe_full <= maybe_full + do_enq - do_deq; 
    end 
  end 
endmodule

module ADDFHXL ( S, CO, A, B, CI);
output S, CO;
input A, B, CI;
xor I0(S, A, B, CI);
  and I1(w1, A, B);
  and I2(w2, A, CI);
  and I3(w3, B, CI);
  or  I4(CO, w1, w2, w3);
  specify
    specparam
      tplh$A$S  = 1.0,
      tphl$A$S  = 1.0,
      tplh$A$CO  = 1.0,
      tphl$A$CO  = 1.0,
      tplh$B$S  = 1.0,
      tphl$B$S  = 1.0,
      tplh$B$CO  = 1.0,
      tphl$B$CO  = 1.0,
      tplh$CI$S  = 1.0,
      tphl$CI$S  = 1.0,
      tplh$CI$CO  = 1.0,
      tphl$CI$CO  = 1.0;
    (A *> S) = (tplh$A$S,  tphl$A$S);
    (A *> CO) = (tplh$A$CO,  tphl$A$CO);
    (B *> S) = (tplh$B$S,  tphl$B$S);
    (B *> CO) = (tplh$B$CO,  tphl$B$CO);
    (CI *> S) = (tplh$CI$S,  tphl$CI$S);
