    if(rst)
      match <= 1'b0;
  end
endmodule

module complexmulttrial(
input [15:0] a_r,
input [15:0] a_i,
input [15:0] b_r,
input [15:0] b_i,
input [15:0] w_r,
input [15:0] w_i,
output [15:0] x_r,
output [15:0] x_i,
output [15:0] y_r,
output [15:0] y_i);
wire [31:0] x_r_int;
wire [31:0] x_i_int;
wire [31:0] y_r_int;
wire [31:0] y_i_int;
wire [31:0] add_r;
wire [31:0] add_i;
wire [31:0] sub_r;
wire [31:0] sub_i;
wire [31:0] mult_r;
wire [31:0] mult_i;
assign add_r = a_r + b_r;
assign add_i = a_i + b_i;
assign sub_r = add_r - w_r;
assign sub_i = add_i - w_i;
assign mult_r = sub_r * sub_i;
assign mult_i = sub_r * sub_i;
assign x_r_int = mult_r + mult_i;
assign x_i_int = mult_r - mult_i;
assign y_r_int = add_r * add_i;
assign y_i_int = add_r * add_i;
assign x_r = x_r_int[31:16];
assign x_i = x_i_int[31:16];
assign y_r = y_r_int[31:16];
assign y_i = y_i_int[31:16];
endmodule

module Control(
   
	input wire clk,rst,
	input [7:0] in3,in2,in1,in0,
	output reg [3:0] anodo,
	output reg [7:0] catodo
    );
localparam N = 18;
	reg [N-1:0] q_reg,q_next;
	
	always @(posedge clk or posedge rst)
	begin
		if(rst)
			q_reg <= 0;
		else
			q_reg <= q_next;
	end
	
	always @(*)
	begin
		q_next = q_reg + 1;
	end
	
	always @(*)
	begin
		case(q_reg[N-2:N-1])
			2'b00: begin
					anodo = 4'b1110;
					catodo = in0;
					end
			2'b01: begin
					anodo = 4'b1101;
					catodo = in1;
					end
			2'b10: begin
					anodo = 4'b1011;
					catodo = in2;
					end
			2'b11: begin
					anodo = 4'b0111;
					catodo = in3;
					end
		endcase
	end
endmodule

