module uart_send(
  input sys_clk,
  input sys_rst_n,
  input uart_en,
  input [7:0] uart_din,
  output reg uart_txd
);
parameter CLK_FREQ = 100000000;
  parameter UART_BPS = 115200;
  localparam BPS_CNT = CLK_FREQ / UART_BPS;
  reg [1:0] uart_en_sync;
  reg tx_flag;
  reg [7:0] tx_data;
  reg [31:0] clk_cnt;
  reg [3:0] tx_cnt;
  always @(posedge sys_clk or negedge sys_rst_n) begin
    if (!sys_rst_n) begin
      uart_en_sync <= 2'b00;
      tx_flag <= 1'b0;
      tx_data <= 8'b0;
      clk_cnt <= 32'b0;
      tx_cnt <= 4'b0;
    end
    else begin
      uart_en_sync <= {uart_en_sync[0], uart_en};
      if (uart_en_sync == 2'b01) begin
        tx_flag <= 1'b1;
        tx_data <= uart_din;
        clk_cnt <= 32'b0;
        tx_cnt <= 4'b0;
      end
      else if (tx_flag) begin
        if (clk_cnt == BPS_CNT - 1) begin
          clk_cnt <= 32'b0;
          if (tx_cnt == 0) begin
            uart_txd <= 1'b0;
            tx_cnt <= tx_cnt + 1'b1;
          end
          else if (tx_cnt < 9) begin
            uart_txd <= tx_data[tx_cnt - 1];
            tx_cnt <= tx_cnt + 1'b1;
          end
          else begin
            uart_txd <= 1'b1;
            tx_flag <= 1'b0;
            tx_cnt <= 4'b0;
          end
        end
        else begin
          clk_cnt <= clk_cnt + 1'b1;
        end
      end
    end
  end
endmodule

