module boardSynchroniser(
    input clk,
	 input synch_en,
    input toggle_en,
    input [1:0] cnt_n,
    input [1:0] cnt_m,
    input opMode,
    output reg synchroStatus = 1'b0,
    inout syncInOut
    );
reg [1:0] counter = 2'b0;
    reg synch = 1'b0;
    reg toggle_en_last = 1'b0;
    wire toggle_en_rising = toggle_en & ~toggle_en_last;
    always @(posedge clk) begin
        toggle_en_last <= toggle_en;
        if (toggle_en_rising) begin
            if (counter == cnt_m) begin
                synch <= 1'b1;
            end
            else if (counter == cnt_n) begin
                synch <= 1'b0;
            end
            counter <= counter + 1'b1;
        end
        if (opMode == 2'b00) begin
            synchroStatus <= synch;
            syncInOut <= synch;
        end
        else begin
            syncInOut <= 1'bz;
            synchroStatus <= 1'bz;
        end
    end
endmodule

