module flag(

	input [2:0]sign,
	input islow,
	input carry_in,


	output reg carry_out,
	output reg led2
);
reg regcarry;

	always @(*)
	begin
		if (islow == 1'b1)
		begin
			carry_out = 1'b0;
			regcarry = carry_in;
		end
		else
		begin
			carry_out = regcarry;
			if (carry_out == 1'b0)
			begin
				if (sign == 3'b000)
					led2 = 1'b0;
				else if (sign == 3'b001)
					led2 = 1'b1;
				else if (sign == 3'b010)
					led2 = 1'b0;
				else if (sign == 3'b011)
					led2 = 1'b1;
				else if (sign == 3'b100)
					led2 = 1'b0;
				else if (sign == 3'b101)
					led2 = 1'b1;
				else if (sign == 3'b110)
					led2 = 1'b0;
				else if (sign == 3'b111)
					led2 = 1'b1;
			end
			else
				led2 = 1'b0;
		end
	end
endmodule

