module diffeq_paj_convert (Xinport, Yinport, Uinport, Aport, DXport, Xoutport, Youtport, Uoutport, CLK, reset);
    input[31:0] Xinport; 
    input[31:0] Yinport; 
    input[31:0] Uinport; 
    input[31:0] Aport; 
    input[31:0] DXport; 
    input CLK; 
    input reset; 
    output[31:0] Xoutport; 
    output[31:0] Youtport; 
    output[31:0] Uoutport;
wire[31:0] temp;
    reg[31:0] x_var;
    reg[31:0] y_var;
    reg[31:0] u_var;
    reg[31:0] x_var_temp;
    reg[31:0] y_var_temp;
    reg[31:0] u_var_temp;
    assign temp = u_var * DXport;
    always @(posedge CLK or posedge reset)
    begin
        if (reset == 1'b1)
        begin
            x_var <= 0;
            y_var <= 0;
            u_var <= 0;
            x_var_temp <= 0;
            y_var_temp <= 0;
            u_var_temp <= 0;
        end
        else
        begin
            if (x_var < Aport)
            begin
                x_var_temp <= x_var + DXport;
                y_var_temp <= y_var + temp;
                u_var_temp <= u_var - (temp * y_var);
                x_var <= x_var_temp;
                y_var <= y_var_temp;
                u_var <= u_var_temp;
            end
        end
    end
    assign Xoutport = x_var;
    assign Youtport = y_var;
    assign Uoutport = u_var;
endmodule

