module scan_hex_led_disp(
    input clk,reset,
    input [3:0] hex3,hex2,hex1,hex0,
    input [3:0] dp,
    output reg[3:0] en, 
    output reg[7:0] sseg
    );
reg [1:0] cnt;
    always @(posedge clk or negedge reset)
    begin
        if(!reset)
            cnt <= 0;
        else
            cnt <= cnt + 1;
    end
    always @(*)
    begin
        case(cnt)
            0:begin
                en = 4'b1110;
                sseg = hex0;
            end
            1:begin
                en = 4'b1101;
                sseg = hex1;
            end
            2:begin
                en = 4'b1011;
                sseg = hex2;
            end
            3:begin
                en = 4'b0111;
                sseg = hex3;
            end
        endcase
    end
    always @(*)
    begin
        case(cnt)
            0:sseg[7] = dp[0];
            1:sseg[7] = dp[1];
            2:sseg[7] = dp[2];
            3:sseg[7] = dp[3];
        endcase
    end
endmodule

module Barrel15L_16(
    input [13:0] data_i,
    input [1:0] shift_i,
    output reg [16:0] data_o
    );
wire [16:0] tmp;
    assign tmp = {{3{data_i[13]}},data_i};
    always @* begin
        case (shift_i)
            2'b00: data_o = tmp;
            2'b01: data_o = tmp << 1;
            2'b10: data_o = tmp << 2;
            2'b11: data_o = tmp << 3;
        endcase
    end
endmodule

module decoder_3to8 
    (input [2:0] a,
     input enable,
     output reg [7:0] y
    );
always @(a or enable)
    begin
        if (enable == 0)
            y = 8'b00000000;
        else
            case (a)
                3'b000: y = 8'b00000001;
                3'b001: y = 8'b00000010;
                3'b010: y = 8'b00000100;
                3'b011: y = 8'b00001000;
                3'b100: y = 8'b00010000;
                3'b101: y = 8'b00100000;
                3'b110: y = 8'b01000000;
                3'b111: y = 8'b10000000;
                default: y = 8'b00000000;
            endcase
    end
endmodule

module Data_Memory(input clk, rst, MemWrite, MemRead, mem_to_reg,
input [31:0] addr, write_data, output [31:0] read_data);
reg [31:0] memory [31:0];
integer i;
initial begin
	for(i=0; i<32; i=i+1) begin
		memory[i] = 0;
	end
end
always @(posedge clk) begin
	if(MemWrite) begin
		memory[addr] = write_data;
	end
end
assign read_data = (MemRead) ? memory[addr] : 0;
endmodule

module binary_updown_counter #(parameter BITS = 1)
        (input wire clk, input wire rst, input wire ena,
         input wire updown, output wire [BITS - 1:0] out, output wire ovf);
reg [BITS - 1:0] cnt;
    wire [BITS - 1:0] enable_wires;

    assign out = cnt;
    assign enable_wires[0] = ena;
    assign ovf = (cnt == 0) ^ (cnt == (2**BITS - 1));

    genvar i;
    generate
        for (i = 0; i < BITS; i = i + 1) begin : gen_counter
            always @(posedge clk or posedge rst) begin
                if (rst) begin
                    cnt[i] <= 0;
                end else if (enable_wires[i]) begin
                    if (updown) begin
                        cnt[i] <= cnt[i] + 1;
                    end else begin
                        cnt[i] <= cnt[i] - 1;
                    end
                end
            end
            assign enable_wires[i + 1] = cnt[i];
        end
    endgenerate
endmodule

module BCD(
		input [15:0] binary,
		output wire [3:0] b,
		output wire [3:0] s,
		output wire [3:0] g,
		output wire [3:0] q
		);
reg [31:0] bcd;
	assign b = bcd[3:0];
	assign s = bcd[7:4];
	assign g = bcd[11:8];
	assign q = bcd[15:12];
	integer i;
	always @(*) begin
		bcd = binary;
		repeat(16) begin
			if(bcd[3:0] > 4)
				bcd[3:0] = bcd[3:0] + 3;
			if(bcd[7:4] > 4)
				bcd[7:4] = bcd[7:4] + 3;
			if(bcd[11:8] > 4)
				bcd[11:8] = bcd[11:8] + 3;
			if(bcd[15:12] > 4)
				bcd[15:12] = bcd[15:12] + 3;
			bcd = bcd >> 1;
		end
	end
endmodule

module Data_Memory 
#(	
	parameter DATA_WIDTH = 32,
	parameter MEMORY_DEPTH = 64
)
(
	input clk, Write_Enable_i, 
	input [DATA_WIDTH-1:0] Write_Data_i,
	input [DATA_WIDTH-1:0]  Address_i,
	output [(DATA_WIDTH-1):0]  Read_Data_o
);
reg [DATA_WIDTH-1:0] Var_i = 32'h10010000;
	reg [DATA_WIDTH-1:0] Memory [MEMORY_DEPTH-1:0];
	reg [DATA_WIDTH-1:0] Effective_Addr;

	assign Effective_Addr = (Address_i - Var_i) >> 2;
	assign Read_Data_o = Memory[Effective_Addr];

	always @(posedge clk)
	begin
		if(Write_Enable_i == 1'b1)
			Memory[Effective_Addr] <= Write_Data_i;
	end
endmodule

