module peridot_ethio_cdb_signal (
	input wire			reset,
	input wire			clk,
	input wire			in_sig,
	output wire			out_sig,
	output wire			riseedge,
	output wire			falledge
);
reg [2:0] sig_reg;

	always @(posedge clk or posedge reset) begin
		if (reset) begin
			sig_reg <= 3'b0;
		end else begin
			sig_reg <= {sig_reg[1:0], in_sig};
		end
	end

	assign out_sig = sig_reg[2];
	assign riseedge = sig_reg[1] & ~sig_reg[2];
	assign falledge = ~sig_reg[1] & sig_reg[2];

endmodule

module IB_ENDPOINT_OP_DONE_BUFFER(
input wire CLK,
input wire RESET,
input wire [15:0] RD_COMPL_TAG,
input wire RD_COMPL_START,
input wire RD_COMPL_DONE,
input wire [15:0] BM_TAG,
input wire BM_DONE,
output wire [15:0] OP_TAG,
output wire OP_DONE
); 

reg [15:0] rd_compl_tag;
reg rd_compl_start;
reg rd_compl_done;
reg [15:0] bm_tag;
reg bm_done;
wire [15:0] rd_compl_tag_out;
wire rd_compl_start_out;
wire rd_compl_done_out;
wire bm_done_out;
wire [15:0] op_tag_out;
wire op_done_out;
  always @(posedge CLK, posedge RESET) begin
    if((RESET == 1'b1)) begin
      rd_compl_tag <= {16{1'b0}};
      rd_compl_start <= 1'b0;
      rd_compl_done <= 1'b0;
      bm_tag <= {16{1'b0}};
      bm_done <= 1'b0;
    end else begin
      rd_compl_tag <= RD_COMPL_TAG;
      rd_compl_start <= RD_COMPL_START;
      rd_compl_done <= RD_COMPL_DONE;
      bm_tag <= BM_TAG;
      bm_done <= BM_DONE;
    end
  end
  assign rd_compl_tag_out = rd_compl_tag;
  assign rd_compl_start_out = rd_compl_start;
  assign rd_compl_done_out = rd_compl_done;
