module pddm (
	input sdi, 
	input signed_data, 
	output [31:0] dout, 
	input ock, uck, 
	input rstn, clk
);
reg [31:0] sigma = 0;
reg [31:0] undersampled_sigma = 0;
wire [31:0] delta = sdi ? 1 : -1;
wire [31:0] deriv = sigma - undersampled_sigma;
always @(posedge clk or negedge rstn) begin
	if (!rstn) begin
		sigma <= 0;
		undersampled_sigma <= 0;
	end
	else begin
		sigma <= sigma + delta;
		if (ock) begin
			undersampled_sigma <= sigma;
		end
		if (uck) begin
			sigma <= 0;
		end
	end
end
assign dout = signed_data ? deriv : deriv[31:0];
endmodule

module RegFile(
    output reg signed  [31:0] ReadData1, ReadData2,
    input [4:0] ReadReg1, ReadReg2, WriteReg,
    input signed [31:0] WriteData,
    input RegWrite, Clk
    );
reg signed [31:0] Registers [31:0];
    always @(negedge Clk)
    begin
        if(ReadReg1 == 0)
            ReadData1 <= 0;
        else
            ReadData1 <= Registers[ReadReg1];
        if(ReadReg2 == 0)
            ReadData2 <= 0;
        else
            ReadData2 <= Registers[ReadReg2];
    end
    always @(posedge Clk)
    begin
        if(RegWrite == 1)
            Registers[WriteReg] <= WriteData;
    end
endmodule

