module gray_Nbits (clk, reset, enable, gray_out);

input wire clk, reset, enable;
output wire [N-1:0]gray_out;
parameter N = 4;
parameter SIZE = N+1;
parameter Zeros = {SIZE{1'b0}};

reg [SIZE-1:0]state;
reg [SIZE-1:0]toggle;

assign gray_out = state[SIZE-2:1];

always @(posedge clk or posedge reset)
begin
	if (reset)
		state <= Zeros;
	else if (enable)
		state <= state ^ toggle;
end

always @(state)
begin
	toggle[0] = 1'b1;
	toggle[SIZE-1:1] = state[SIZE-1:1] ^ (state[SIZE-2:0] << 1);
end

endmodule

