module Fibonacci_Series
( 
    input wire CLK_IN,
    input wire RST_N,
    output wire [7:0]SEQUENCE
);
reg [7:0] a = 0;
    reg [7:0] b = 1;
    reg [7:0] c = 0;
    always @(posedge CLK_IN or negedge RST_N)
    begin
        if(!RST_N)
        begin
            a <= 0;
            b <= 1;
            c <= 0;
        end
        else
        begin
            c <= a + b;
            a <= b;
            b <= c;
        end
    end
    assign SEQUENCE = c;
endmodule

