module adapter_rgb_2_ppfifo #(
  parameter                 DATA_WIDTH = 24
)(
  input                             clk,
  input                             rst,

  input         [23:0]              i_rgb,
  input                             i_h_sync,
  input                             i_h_blank,
  input                             i_v_sync,
  input                             i_v_blank,
  input                             i_data_en,


  output                            o_ppfifo_clk,
  input       [1:0]                 i_ppfifo_rdy,
  output  reg [1:0]                 o_ppfifo_act,
  input       [23:0]                i_ppfifo_size,
  output  reg                       o_ppfifo_stb,
  output  reg [DATA_WIDTH - 1:0]    o_ppfifo_data


);
localparam [1:0]
  IDLE = 0,
  READY = 1,
  RELEASE = 2;

reg [1:0] state = IDLE;
reg [23:0] r_count = 0;

always @(posedge clk or posedge rst) begin
  if (rst) begin
    r_count <= 0;
    o_ppfifo_act <= 0;
    o_ppfifo_stb <= 0;
    o_ppfifo_data <= 0;
    state <= IDLE;
  end
  else begin
    case (state)
      IDLE: begin
        if (i_ppfifo_rdy[0] == 1'b1) begin
          o_ppfifo_act <= 1;
          state <= READY;
        end
      end
      READY: begin
        if (i_h_blank == 1'b0) begin
          if (r_count < i_ppfifo_size) begin
            o_ppfifo_stb <= 1;
            o_ppfifo_data <= i_rgb;
            r_count <= r_count + 1;
          end
          else begin
            o_ppfifo_stb <= 0;
            state <= RELEASE;
          end
        end
        else begin
          o_ppfifo_stb <= 0;
          state <= RELEASE;
        end
      end
      RELEASE: begin
        o_ppfifo_act <= 0;
        r_count <= 0;
        state <= IDLE;
      end
    endcase
  end
end

assign o_ppfifo_clk = clk;

endmodule

