module DelayLoop(MR,Timeout,Clock) ;
input			MR, Clock;
output reg	Timeout;
parameter	Divider = 100000;
reg [26:0]	counter;
always @ (counter)
begin
	if (counter == Divider)
		Timeout = 1;
	else
		Timeout = 0;
end
always @ (posedge Clock)
begin
	if (MR == 1)
		counter <= 0;
	else if (Timeout == 0)
		counter <= counter + 1;
end
endmodule

