module udpAppMux_txLengthNetwork_fifo
#(parameter
    DATA_BITS  = 8,
    DEPTH_BITS = 4
)(
    input  wire                 clk,
    input  wire                 aclr,
    output wire                 empty_n,
    output wire                 full_n,
    input  wire                 read,
    input  wire                 write,
    output wire [DATA_BITS-1:0] dout,
    input  wire [DATA_BITS-1:0] din
);
localparam
    DEPTH = 1 << DEPTH_BITS;

reg                   empty;
reg                   full;
reg  [DEPTH_BITS-1:0] index;
reg  [DATA_BITS-1:0]  mem[0:DEPTH-1];

assign empty_n = ~empty;
assign full_n  = ~full;
assign dout    = mem[index];


always @(posedge clk or posedge aclr) begin
    if (aclr)
        empty <= 1'b1;
    else if (empty & write & ~read)
        empty <= 1'b0;
    else if (~empty & ~write & read & (index==1'b0))
        empty <= 1'b1;
end


always @(posedge clk or posedge aclr) begin
    if (aclr)
        full <= 1'b0;
    else if (full & read & ~write)
        full <= 1'b0;
    else if (~full & ~read & write & (index==DEPTH-2'd2))
        full <= 1'b1;
end


always @(posedge clk or posedge aclr) begin
    if (aclr)
        index <= {DEPTH_BITS{1'b1}};
    else if (~empty & ~write & read)
        index <= index - 1'b1;
    else if (~full & ~read & write)
        index <= index + 1'b1;
end


always @(posedge clk) begin
    if (~full & write) mem[0] <= din;
end

genvar i;
generate
    for (i = 1; i < DEPTH; i = i + 1) begin : gen_sr
        always @(posedge clk) begin
            if (~full & write) mem[i] <= mem[i-1];
        end
    end
endgenerate

endmodule

module Counter_Controller #(
    parameter   DWIDTH = 7
)(
    input                   clk,
    input                   rst_n,
    input                   start_i,
    input   [DWIDTH-1:0]    cnt_val_i,
    input   [DWIDTH-1:0]    cnt_i,
    output                  run_o,
    output                  done_o
);
localparam  S_IDLE  = 2'b00;
    localparam  S_RUN   = 2'b01;
    localparam  S_DONE  = 2'b10;

    reg [1:0] state, state_n;
    reg [DWIDTH-1:0] cnt_val, cnt_val_n;
    reg run, done;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= S_IDLE;
            cnt_val <= 0;
            run <= 0;
            done <= 0;
        end
        else begin
            state <= state_n;
            cnt_val <= cnt_val_n;
            run <= run;
            done <= done;
        end
    end

    always @(*) begin
        case (state)
            S_IDLE: begin
                run = 0;
                done = 0;
                if (start_i) begin
                    state_n = S_RUN;
                    cnt_val_n = cnt_val_i;
                end
                else begin
                    state_n = S_IDLE;
                    cnt_val_n = cnt_val;
                end
            end
            S_RUN: begin
                run = 1;
                done = 0;
                if (cnt_i == cnt_val) begin
                    state_n = S_DONE;
                    cnt_val_n = cnt_val;
                end
                else begin
                    state_n = S_RUN;
                    cnt_val_n = cnt_val + 1;
                end
            end
            S_DONE: begin
                run = 0;
                done = 1;
                state_n = S_IDLE;
                cnt_val_n = cnt_val;
            end
            default: begin
                state_n = S_IDLE;
                cnt_val_n = cnt_val;
            end
        endcase
    end

    assign run_o = run;
    assign done_o = done;

endmodule

