wire [31:0] x_mask;
wire [31:0] f_masked;
wire [31:0] incr;
wire [31:0] f_incr;
wire [31:0] f_out;
wire [31:0] res;
  assign len_raw = 8'b00000000 - f[30:23] + 8'b00000001;
  assign len = f[30:23] == 8'b00000000 ? 8'b00000000 : len_raw;
  assign x_mask = 32'b00000000000000000000000000000000 >> len;
  assign f_masked = f & x_mask;
  assign incr = 32'b00000000000000000000000000000001 << (len - 1);
  assign f_incr = f_masked + incr;
  assign f_out = f[30:23] == 8'b00000000 ? f : f_incr;
  assign res = f[31] == 1'b1 ? 32'b10000000000000000000000000000000 : f_out[31:23] == 8'b00000000 ? f_out : f_out[31:23] == 8'b00000001 ? f_out + 32'b00000000000000000000000000000001 : f_out;
  always @(posedge clk) begin
    g <= res;
  end
