module SynFifo #
(
    parameter DATA_WIDTH = 8,
    parameter FIFO_DEPTH = 256
)
(clk,arstn,data_in,wrreq,rdreq,data_out,usedw,empty,full);

input clk;
input arstn;
input [DATA_WIDTH-1:0]data_in;
input wrreq;
input rdreq;
output [DATA_WIDTH-1:0]data_out;
output reg [clog2_FIFO_DEPTH:0]usedw;
output empty;
output full;
parameter clog2_FIFO_DEPTH = $clog2(FIFO_DEPTH);

reg [clog2_FIFO_DEPTH:0]wrptr;
reg [clog2_FIFO_DEPTH:0]rdptr;
reg [clog2_FIFO_DEPTH:0]wrphase;
reg [clog2_FIFO_DEPTH:0]rdphase;
reg [DATA_WIDTH-1:0]fifo_mem [0:FIFO_DEPTH-1];

wire wrreq_phase = wrreq & ~full;
wire rdreq_phase = rdreq & ~empty;

always @(posedge clk or negedge arstn)
begin
    if(!arstn)
    begin
        wrptr <= 0;
        rdptr <= 0;
        wrphase <= 0;
        rdphase <= 0;
    end
    else
    begin
        if(wrreq_phase)
        begin
            wrptr <= wrptr + 1;
            wrphase <= wrphase + 1;
        end
        if(rdreq_phase)
        begin
            rdptr <= rdptr + 1;
            rdphase <= rdphase + 1;
        end
    end
end

always @(posedge clk or negedge arstn)
begin
    if(!arstn)
    begin
        usedw <= 0;
    end
    else
    begin
        usedw <= wrphase - rdphase;
    end
end

always @(posedge clk or negedge arstn)
begin
    if(!arstn)
    begin
        fifo_mem[0] <= 0;
    end
    else
    begin
        if(wrreq_phase)
        begin
            fifo_mem[wrptr] <= data_in;
        end
    end
end

assign data_out = fifo_mem[rdptr];
assign empty = (wrphase == rdphase);
assign full = (wrphase == rdphase) & (wrreq_phase ^ rdreq_phase);

endmodule

