    reg [7:0] clkA_data;
    reg [7:0] clkB_data;
    always @(posedge clkA) begin
        FlagToggle_clkA <= FlagToggle_clkA ^ FlagIn_clkA;
    end
    always @(posedge clkB) begin
        SyncA_clkB <= {SyncA_clkB[1:0], FlagToggle_clkA};
    end
    always @(posedge clkA) begin
        if (SyncA_clkB == 3'b001) begin
            clkA_data <= dataA;
        end
    end
    always @(posedge clkB) begin
        if (SyncA_clkB == 3'b100) begin
            clkB_data <= clkA_data;
        end
    end
    assign FlagOut_clkB = SyncA_clkB[2];
    assign dataB = clkB_data;
endmodule

module mulor_3_stage_signed_10_bit(
