    comparator_3bit uut(A, B, A_greater, A_equal, A_less);
    initial begin
        for (i = 0; i < 100; i = i + 1) begin
            A = $random % 8;
            B = $random % 8;
            if (A > B) begin
                if (A_greater != 1'b1 || A_equal != 1'b0 || A_less != 1'b0) begin
                    error = error + 1;
                    $display("Error at time %d",$time);
                    $display("A = %b, B = %b, A_greater = %b, A_equal = %b, A_less = %b",$time, A, B, A_greater, A_equal, A_less);
                end
            end
            else if (A == B) begin
                if (A_greater != 1'b0 || A_equal != 1'b1 || A_less != 1'b0) begin
                    error = error + 1;
                    $display("Error at time %d",$time);
                    $display("A = %b, B = %b, A_greater = %b, A_equal = %b, A_less = %b",$time, A, B, A_greater, A_equal, A_less);
                end
            end
            else begin
                if (A_greater != 1'b0 || A_equal != 1'b0 || A_less != 1'b1) begin
                    error = error + 1;
                    $display("Error at time %d",$time);
                    $display("A = %b, B = %b, A_greater = %b, A_equal = %b, A_less = %b",$time, A, B, A_greater, A_equal, A_less);
                end
            end
        end
        if (error == 0) begin
            $display("=========== Your Design Passed ===========");
        end
        else begin
            $display("=========== Test completed with %d/100 ===========", 100 - error);
        end
        $finish;
    end
endmodule

