module fsm_trafic_light(clk,reset, red,yellow, green);
input clk, reset;

output red,yellow,green;
reg [1:0] state, next_state; 

always @(posedge clk or posedge reset)
begin
	if (reset)
		state <= 0;
	else
		state <= next_state;
end

always @(*)
begin
	case (state)
		0: next_state = 1;
		1: next_state = 2;
		2: next_state = 3;
		3: next_state = 0;
		default: next_state = 0;
	endcase
end

always @(*)
begin
	case (state)
		0: begin red = 1; yellow = 0; green = 0; end
		1: begin red = 0; yellow = 1; green = 0; end
		2: begin red = 0; yellow = 0; green = 1; end
		3: begin red = 1; yellow = 1; green = 0; end
		default: begin red = 0; yellow = 0; green = 0; end
	endcase
end

endmodule

