module key_filter(clk,rst_n,key_pin,key_status,key_event);
	input clk;
	input rst_n;
	input key_pin;
	output reg key_status;
	output reg key_event;
reg [3:0] key_reg;
	reg [3:0] cnt;
	reg [1:0] key_status_reg;
	reg [1:0] key_status_next;
	always @(posedge clk or negedge rst_n) begin
		if(!rst_n) begin
			key_status_reg <= 2'b00;
		end
		else begin
			key_status_reg <= key_status_next;
		end
	end
	always @(key_status_reg or key_pin) begin
		case(key_status_reg)
			2'b00: begin
				if(key_pin == 1'b0) begin
					key_status_next = 2'b01;
				end
				else begin
					key_status_next = 2'b00;
				end
			end
			2'b01: begin
				if(key_pin == 1'b0) begin
					if(cnt == 4'd15) begin
						key_status_next = 2'b10;
					end
					else begin
						key_status_next = 2'b01;
					end
				end
				else begin
					key_status_next = 2'b00;
				end
			end
			2'b10: begin
				if(key_pin == 1'b1) begin
					key_status_next = 2'b11;
				end
				else begin
					key_status_next = 2'b10;
				end
			end
			2'b11: begin
				if(key_pin == 1'b1) begin
					if(cnt == 4'd15) begin
						key_status_next = 2'b00;
					end
					else begin
						key_status_next = 2'b11;
					end
				end
				else begin
					key_status_next = 2'b10;
				end
			end
		endcase
	end
	always @(posedge clk or negedge rst_n) begin
		if(!rst_n) begin
			key_reg <= 4'b0000;
			cnt <= 4'b0000;
		end
		else begin
			key_reg <= {key_reg[2:0],key_pin};
			if(key_status_reg == 2'b01) begin
				cnt <= cnt + 4'b0001;
			end
			else if(key_status_reg == 2'b11) begin
				cnt <= cnt + 4'b0001;
			end
			else begin
				cnt <= 4'b0000;
			end
		end
	end
	always @(key_status_reg) begin
		case(key_status_reg)
			2'b00: begin
				key_status <= 1'b0;
				key_event <= 1'b0;
			end
			2'b01: begin
				key_status <= 1'b1;
				key_event <= 1'b0;
			end
			2'b10: begin
				key_status <= 1'b1;
				key_event <= 1'b0;
			end
			2'b11: begin
				key_status <= 1'b0;
				key_event <= 1'b1;
			end
		endcase
	end
endmodule

module alu(input signed [31:0] x, input signed [31:0] y, input [3:0] alu_ctrl, output reg signed [31:0] result, output reg zero);
always @(*) begin
        case (alu_ctrl)
            4'b0000: result = x + y;
            4'b0001: result = x - y;
            4'b0010: result = x * y;
            4'b0011: result = x / y;
            4'b0100: result = x & y;
            4'b0101: result = x | y;
            4'b0110: result = x ^ y;
            4'b0111: result = x < y ? 1 : 0;
            default: result = 0;
        endcase
        zero = (result == 0);
    end
endmodule

