module APB_master(input Transfer,              
                  input Wr_Rd,                 
                  input [4:0] Address,         
                  input [31:0] write_data,     
                  output reg [31:0] read_data, 
                  input PCLK,                  
                  input PRESETn,               
                  input PREADY,                
                  input [31:0] PRDATA,         
                  input PSLVERR,               
                  output reg [4:0] PADDR,      
                  output reg PSELx,            
                  output reg PENABLE,          
                  output reg PWRITE,           
                  output reg [31:0] PWDATA);
parameter IDLE = 2'b00;
    parameter SETUP = 2'b01;
    parameter ACCESS = 2'b10;
    reg [1:0] state, next_state;
    always @(posedge PCLK or negedge PRESETn) begin
        if (!PRESETn) begin
            state <= IDLE;
        end else begin
            state <= next_state;
        end
    end
    always @(*) begin
        case (state)
            IDLE: begin
                PSELx = 1'b0;
                PENABLE = 1'b0;
                PWRITE = 1'b0;
                PWDATA = 32'b0;
                PADDR = 5'b0;
                if (Transfer) begin
                    next_state = SETUP;
                end else begin
                    next_state = IDLE;
                end
            end
            SETUP: begin
                PSELx = 1'b1;
                PENABLE = 1'b1;
                PWRITE = Wr_Rd;
                PWDATA = write_data;
                PADDR = Address;
                if (PREADY) begin
                    next_state = ACCESS;
                end else begin
                    next_state = SETUP;
                end
            end
            ACCESS: begin
                PSELx = 1'b1;
                PENABLE = 1'b1;
                PWRITE = Wr_Rd;
                PWDATA = write_data;
                PADDR = Address;
                if (PREADY) begin
                    if (Wr_Rd) begin
                        read_data = PRDATA;
                    end
                    next_state = IDLE;
                end else begin
                    next_state = ACCESS;
                end
            end
            default: begin
                next_state = IDLE;
            end
        endcase
    end
endmodule

