module cyclonev_bias_logic (
    clk,
    shiftnld,
    captnupdt,
    mainclk,
    updateclk,
    capture,
    update
    );


input  clk;
input  shiftnld;
input  captnupdt;


output mainclk;
output updateclk;
output capture;
output update;
reg mainclk_tmp;
reg updateclk_tmp;
reg capture_tmp;
reg update_tmp;

wire high = 1'b1;

assign mainclk = mainclk_tmp & high;
assign updateclk = updateclk_tmp & high;
assign capture = capture_tmp & high;
assign update = update_tmp & high;

always @(captnupdt or shiftnld or clk)
    begin
        mainclk_tmp = 1'b0;
        updateclk_tmp = 1'b0;
        capture_tmp = 1'b0;
        update_tmp = 1'b0;
        case ({captnupdt, shiftnld})
            2'b00: begin
                mainclk_tmp = 1'b1;
                updateclk_tmp = 1'b1;
                capture_tmp = 1'b0;
                update_tmp = 1'b0;
            end
            2'b01: begin
                mainclk_tmp = 1'b1;
                updateclk_tmp = 1'b0;
                capture_tmp = 1'b1;
                update_tmp = 1'b0;
            end
            2'b10: begin
                mainclk_tmp = 1'b0;
                updateclk_tmp = 1'b1;
                capture_tmp = 1'b0;
                update_tmp = 1'b1;
            end
            2'b11: begin
                mainclk_tmp = 1'b0;
                updateclk_tmp = 1'b0;
                capture_tmp = 1'b1;
                update_tmp = 1'b1;
            end
        endcase
    end

