module tb_file_to_dvp
#(
	parameter FILE     = "in.bin",
	parameter BITS     = 8, 
	parameter H_FRONT  = 50,
	parameter H_PULSE  = 100,
	parameter H_BACK   = 50,
	parameter H_DISP   = 1280,
	parameter V_FRONT  = 10,
	parameter V_PULSE  = 20,
	parameter V_BACK   = 10,
	parameter V_DISP   = 960,
	parameter H_POL    = 0,
	parameter V_POL    = 1
)
(
	input             xclk,
	input             rst_n,
	output            pclk,
	output reg        href,
	output reg        hsync,
	output reg        vsync,
	output [BITS-1:0] data
);
localparam H_TOTAL = H_FRONT + H_PULSE + H_BACK + H_DISP;
	localparam V_TOTAL = V_FRONT + V_PULSE + V_BACK + V_DISP;
	reg [31:0] pix_cnt;
	reg [31:0] line_cnt;
	reg [31:0] data_cnt;
	reg [BITS-1:0] raw_data;
	reg [BITS-1:0] buffer [0:(H_DISP*V_DISP)-1];
	assign pclk = xclk;
	always @(posedge xclk or negedge rst_n) begin
		if (!rst_n) begin
			pix_cnt <= 0;
			line_cnt <= 0;
			data_cnt <= 0;
			raw_data <= 0;
			href <= 0;
			hsync <= 0;
			vsync <= 0;
			data <= 0;
		end
		else begin
			if (pix_cnt == H_TOTAL) begin
				pix_cnt <= 0;
				line_cnt <= line_cnt + 1;
				if (line_cnt == V_TOTAL) begin
					line_cnt <= 0;
				end
			end
			else begin
				pix_cnt <= pix_cnt + 1;
			end
			if (line_cnt < V_FRONT) begin
				vsync <= V_POL;
			end
			else if (line_cnt < V_FRONT + V_PULSE) begin
				vsync <= ~V_POL;
			end
			else if (line_cnt < V_FRONT + V_PULSE + V_BACK) begin
				vsync <= V_POL;
			end
			else begin
				vsync <= 0;
			end
			if (pix_cnt < H_FRONT) begin
				hsync <= H_POL;
			end
			else if (pix_cnt < H_FRONT + H_PULSE) begin
				hsync <= ~H_POL;
			end
			else if (pix_cnt < H_FRONT + H_PULSE + H_BACK) begin
				hsync <= H_POL;
			end
			else begin
				hsync <= 0;
			end
			if (line_cnt >= V_FRONT + V_PULSE + V_BACK && pix_cnt >= H_FRONT + H_PULSE + H_BACK) begin
				href <= 1;
				data <= raw_data;
			end
			else begin
				href <= 0;
				data <= 0;
			end
			if (line_cnt >= V_FRONT + V_PULSE + V_BACK && pix_cnt >= H_FRONT + H_PULSE + H_BACK) begin
				data_cnt <= data_cnt + 1;
				raw_data <= buffer[data_cnt];
			end
		end
	end
	initial begin
		$readmemb(FILE, buffer);
	end
endmodule

