module maxFinder #(parameter numInput=10,parameter inputWidth=16)(
input           i_clk,
input [(numInput*inputWidth)-1:0]   i_data,
input           i_valid,
output reg [31:0]o_data,
output  reg     o_data_valid
);
reg [inputWidth-1:0]inDataBuffer [0:numInput-1];
reg [31:0]counter;
reg [inputWidth-1:0]maxValue;
always @(posedge i_clk) begin
    if(i_valid) begin
        o_data_valid <= 0;
        counter <= 0;
        maxValue <= 0;
        o_data <= 0;
    end
    else begin
        if(counter < numInput) begin
            inDataBuffer[counter] <= i_data[(counter*inputWidth)+:inputWidth];
            counter <= counter + 1;
        end
        else begin
            o_data_valid <= 1;
            o_data <= 0;
            for(counter = 0; counter < numInput; counter = counter + 1) begin
                if(inDataBuffer[counter] > maxValue) begin
                    maxValue <= inDataBuffer[counter];
                    o_data <= counter;
                end
            end
        end
    end
end
endmodule

