module ControlFSM (clk, reset, irq, read, write, iack, ir, alu_flags,
    addr_sel, load_sel, count_sel, count_up, top_enable, alu_enable, alu_op);
input clk, reset;
input irq;              
input [7:0] ir;         
input [2:0] alu_flags;     
output read, write, iack;                   
output [1:0] addr_sel, load_sel, count_sel; 
output count_up, top_enable, alu_enable;    
output [5:0] alu_op;
reg [3:0] ustate;
reg [21:0] ucode [0:15];
wire [3:0] nx_ustate;
initial begin
    $readmemh("microcode.hex", ucode);
    ustate = 4'b0000;
end
assign read = ucode[ustate][21];
assign write = ucode[ustate][20];
assign iack = ucode[ustate][19];
assign addr_sel = ucode[ustate][18:17];
assign load_sel = ucode[ustate][16:15];
assign count_sel = ucode[ustate][14:13];
assign count_up = ucode[ustate][12];
assign top_enable = ucode[ustate][11];
assign alu_enable = ucode[ustate][10];
assign alu_op = ucode[ustate][9:4];
assign nx_ustate = ucode[ustate][3:0];
always @(posedge clk or posedge reset) begin
    if (reset) begin
        ustate <= 4'b0000;
    end else begin
        ustate <= nx_ustate;
    end
end
endmodule

