    else begin
      r_RST <= 1'b0;
    end
  end
  assign o_RST = r_RST;
endmodule

module sonar(
input clk, rst_n, 
input do_measure,
input sonar_pulse,
output reg [7:0] inches,
output reg sonar_trigger = 0,
output reg READY = 0
);
reg [1:0] state, next_state;
reg [31:0] timeCount = 0;
reg [31:0] timeoutCounter = 0;
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= 0;
    end else begin
        state <= next_state;
    end
end
always @(*) begin
    case (state)
        0: begin
            READY = 1;
            if (do_measure) begin
                next_state = 1;
            end else begin
                next_state = 0;
            end
        end
        1: begin
            READY = 0;
            next_state = 2;
        end
        2: begin
            READY = 0;
            if (sonar_pulse) begin
                next_state = 3;
            end else begin
                next_state = 2;
            end
        end
        3: begin
            READY = 0;
            if (sonar_pulse) begin
                next_state = 3;
            end else begin
                next_state = 0;
            end
        end
        default: begin
            READY = 0;
            next_state = 0;
        end
    endcase
end
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        timeCount <= 0;
    end else begin
        if (state == 3) begin
            timeCount <= timeCount + 1;
        end else begin
            timeCount <= 0;
        end
    end
end
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        inches <= 0;
    end else begin
        if (state == 3) begin
            inches <= (timeCount * 100) / 16000;
        end else begin
            inches <= 0;
        end
    end
end
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        timeoutCounter <= 0;
    end else begin
        if (state == 0) begin
            timeoutCounter <= 0;
        end else begin
            timeoutCounter <= timeoutCounter + 1;
        end
    end
end
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        sonar_trigger <= 0;
    end else begin
        if (state == 1) begin
            sonar_trigger <= 1;
        end else begin
            sonar_trigger <= 0;
        end
    end
end
endmodule

