    input   i_clk,
    output  o_hsync,
    output  o_vsync,
    output reg [9:0] o_col_count = 0,
    output reg [9:0] o_row_count = 0
);
parameter COLS = 10'd640;
    parameter ROWS = 10'd480;
    parameter ACT_COLS = 10'd640;
    parameter ACT_ROWS = 10'd480;
    parameter HSYNC_START = 10'd656;
    parameter HSYNC_END = 10'd752;
    parameter VSYNC_START = 10'd490;
    parameter VSYNC_END = 10'd492;
