        if (o_col_count == COLS) begin
            o_col_count <= 0;
            if (o_row_count == ROWS) begin
                o_row_count <= 0;
            end
            else begin
                o_row_count <= o_row_count + 1;
            end
        end
        else begin
            o_col_count <= o_col_count + 1;
        end
    end
    assign o_hsync = (o_col_count >= HSYNC_START) && (o_col_count < HSYNC_END) ? 1'b0 : 1'b1;
