    input  [3                   :0] cpu_data_wen,     
    input  [31                  :0] cpu_data_addr,    
    input  [31                  :0] cpu_data_wdata,   
    output [31                  :0] cpu_data_rdata,   
    output                          data_sram_en,     
    output [3                   :0] data_sram_wen,    
    output [31                  :0] data_sram_addr,   
