module db (
        input clk, n_reset, button_in,
        output reg out
    );
parameter maxbit = 16;
    reg [maxbit-1:0] q_reg, q_next;
    wire q_add, q_reset;
    wire f1, f2;
    assign q_add = q_reg < 16'h0000 ? 1'b1 : 1'b0;
    assign q_reset = q_reg == 16'h0000 ? 1'b1 : 1'b0;
    assign f1 = q_reg == 16'h0000 ? 1'b0 : 1'b1;
    assign f2 = q_reg == 16'h0000 ? button_in : f1;
    always @(posedge clk or negedge n_reset) begin
        if (!n_reset) begin
            q_reg <= 16'h0000;
        end else begin
            q_reg <= q_next;
        end
    end
    always @(q_add, q_reset, f2) begin
        case ({q_add, q_reset})
            2'b01: q_next = 16'h0000;
            2'b10: q_next = f2;
            default: q_next = q_reg + 1'b1;
        endcase
    end
    always @(q_reg) begin
        if (q_reg == 16'h0000) begin
            out <= f2;
        end
    end
endmodule

