module FIFO(
    input clock,
    input sclr,
    input rdreq, wrreq,
    output reg full, empty,
    input [7 : 0] data,
    output [7 : 0] q
);
reg [7 : 0] mem [0 : 15];
    reg [3 : 0] wp, rp;
    reg w_flag, r_flag;
    always @(posedge clock or posedge sclr) begin
        if (sclr) begin
            wp <= 0;
            rp <= 0;
            w_flag <= 0;
            r_flag <= 0;
        end
        else begin
            if (wrreq) begin
                mem[wp] <= data;
                wp <= wp + 1;
                w_flag <= 1;
            end
            if (rdreq) begin
                rp <= rp + 1;
                r_flag <= 1;
            end
        end
    end
    always @(*) begin
        if (w_flag && !r_flag && (wp == rp)) begin
            full <= 1;
            empty <= 0;
        end
        else if (!w_flag && r_flag && (wp == rp)) begin
            full <= 0;
            empty <= 1;
        end
        else begin
            full <= 0;
            empty <= 0;
        end
    end
    assign q = mem[rp];
endmodule

