module AdderTreePipelined
#(
    parameter DATA_WIDTH=32,
    parameter LENGTH=8,
    parameter OUT_WIDTH=DATA_WIDTH+$clog2(LENGTH),
    parameter DELAT_STAGES=$clog2(LENGTH)
)
(
    input rst,
    input clk,
    input in_advance,
    input signed [LENGTH*DATA_WIDTH-1:0] in_addends,
    output signed [OUT_WIDTH-1:0] out_sum
);
generate
    if(LENGTH==1)
    begin
        if(DELAT_STAGES==0)
        begin
            assign out_sum = in_addends;
        end
        else
        begin
            assign out_sum = #1 in_addends;
        end
    end
    else
    begin
        localparam LEFT_LENGTH = LENGTH/2;
        localparam RIGHT_LENGTH = LENGTH-LEFT_LENGTH;
        localparam LEFT_OUT_WIDTH = DATA_WIDTH+$clog2(LEFT_LENGTH);
        localparam RIGHT_OUT_WIDTH = DATA_WIDTH+$clog2(RIGHT_LENGTH);
        localparam LEFT_DELAT_STAGES = DELAT_STAGES-1;
        localparam RIGHT_DELAT_STAGES = DELAT_STAGES-1;
        wire signed [LEFT_OUT_WIDTH-1:0] left_sum;
        wire signed [RIGHT_OUT_WIDTH-1:0] right_sum;
        AdderTreePipelined
        #(
            .DATA_WIDTH(DATA_WIDTH),
            .LENGTH(LEFT_LENGTH),
            .OUT_WIDTH(LEFT_OUT_WIDTH),
            .DELAT_STAGES(LEFT_DELAT_STAGES)
        )
        left_adder_tree
        (
            .rst(rst),
            .clk(clk),
            .in_advance(in_advance),
            .in_addends(in_addends[(LEFT_LENGTH*DATA_WIDTH)-1:0]),
            .out_sum(left_sum)
        );
        AdderTreePipelined
        #(
            .DATA_WIDTH(DATA_WIDTH),
            .LENGTH(RIGHT_LENGTH),
            .OUT_WIDTH(RIGHT_OUT_WIDTH),
            .DELAT_STAGES(RIGHT_DELAT_STAGES)
        )
        right_adder_tree
        (
            .rst(rst),
            .clk(clk),
            .in_advance(in_advance),
            .in_addends(in_addends[(LENGTH*DATA_WIDTH)-1:LEFT_LENGTH*DATA_WIDTH]),
            .out_sum(right_sum)
        );
        assign out_sum = left_sum + right_sum;
    end
endgenerate
endmodule

