module sr_latch(NQ, Q, S, R);
output Q, NQ;
input S, R;
reg state = 1;
assign #5 Q = state;
assign #5 NQ = ~state;
always @(S or R)
begin
	if(S == 1)
		state = 1;
	else if(R == 1)
		state = 0;
end
endmodule

module MUX2_REQ_BRIDGE
#(
    parameter ID_WIDTH   = 20,
    parameter ADDR_WIDTH = 32,
    parameter DATA_WIDTH = 32,
    parameter AUX_WIDTH  = 6,
    parameter BE_WIDTH   = DATA_WIDTH/8
)
(
    input  logic                              data_req_CH0_i,
    input  logic [ADDR_WIDTH-1:0]             data_add_CH0_i,
    input  logic                              data_wen_CH0_i,
    input  logic [DATA_WIDTH-1:0]             data_wdata_CH0_i,
    input  logic [BE_WIDTH-1:0]               data_be_CH0_i,
    input  logic [ID_WIDTH-1:0]               data_ID_CH0_i,
    input  logic [AUX_WIDTH-1:0]              data_aux_CH0_i,
    output logic                              data_gnt_CH0_o,


    input  logic                              data_req_CH1_i,
    input  logic [ADDR_WIDTH-1:0]             data_add_CH1_i,
    input  logic                              data_wen_CH1_i,
    input  logic [DATA_WIDTH-1:0]             data_wdata_CH1_i,
    input  logic [BE_WIDTH-1:0]               data_be_CH1_i,
    input  logic [ID_WIDTH-1:0]               data_ID_CH1_i,
    input  logic [AUX_WIDTH-1:0]              data_aux_CH1_i,
    output logic                              data_gnt_CH1_o,

    output  logic                             data_req_o,
    output  logic [ADDR_WIDTH-1:0]            data_add_o,
    output  logic                             data_wen_o,
    output  logic [DATA_WIDTH-1:0]            data_wdata_o,
    output  logic [BE_WIDTH-1:0]              data_be_o,
    output  logic [ID_WIDTH-1:0]              data_ID_o,
    output  logic [AUX_WIDTH-1:0]             data_aux_o,
    input   logic                             data_gnt_i,

    input   logic                             clk,
    input   logic                             rst_n
);
logic RR_FLAG;
    logic SEL;
    logic [ID_WIDTH-1:0] DATA_ID;
    logic [AUX_WIDTH-1:0] DATA_AUX;
    logic [DATA_WIDTH-1:0] DATA_WDATA;
    logic [BE_WIDTH-1:0] DATA_BE;
    logic [ADDR_WIDTH-1:0] DATA_ADD;
    logic DATA_WEN;

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            RR_FLAG <= 1'b0;
        end
        else begin
            RR_FLAG <= data_gnt_i ? ~RR_FLAG : RR_FLAG;
        end
    end

    assign SEL = data_req_CH0_i & data_req_CH1_i ? RR_FLAG : data_req_CH0_i;
    assign DATA_ID = SEL ? data_ID_CH1_i : data_ID_CH0_i;
    assign DATA_AUX = SEL ? data_aux_CH1_i : data_aux_CH0_i;
    assign DATA_WDATA = SEL ? data_wdata_CH1_i : data_wdata_CH0_i;
    assign DATA_BE = SEL ? data_be_CH1_i : data_be_CH0_i;
    assign DATA_ADD = SEL ? data_add_CH1_i : data_add_CH0_i;
    assign DATA_WEN = SEL ? data_wen_CH1_i : data_wen_CH0_i;

    assign data_req_o = data_req_CH0_i | data_req_CH1_i;
    assign data_add_o = DATA_ADD;
    assign data_wen_o = DATA_WEN;
    assign data_wdata_o = DATA_WDATA;
    assign data_be_o = DATA_BE;
    assign data_ID_o = DATA_ID;
    assign data_aux_o = DATA_AUX;

    assign data_gnt_CH0_o = SEL ? 1'b0 : data_gnt_i;
    assign data_gnt_CH1_o = SEL ? data_gnt_i : 1'b0;

endmodule

module jk_flop (input J, K, clk,
                output reg Q, Qbar);
always @(posedge clk)
    begin
        if (J & K)
            Q <= ~Q;
        else if (J)
            Q <= 1;
        else if (K)
            Q <= 0;
    end
    assign Qbar = ~Q;
endmodule

