module I_SQRT_2(
input wire [31:0] n,
input wire CLK,
input wire RST_n,
input wire EN,
input wire SEL,
output wire VAL,
output wire Z,
output wire [31:0] out_sqrt
); 

wire [31:0] x_0 = 1.0;
wire [31:0] x_i_mux;
wire [31:0] x_i;
wire [31:0] x_next;
wire [31:0] sqrt;
wire [31:0] sqrt_reg;
wire [31:0] out_sqrt_reg;
wire [31:0] val_comb;
wire [31:0] z_comb;
wire [31:0] val_ff;
wire [31:0] z_ff;
  assign x_i_mux = SEL == 1'b1 ? x_0 : x_i;
  assign x_i = x_i_mux;
  assign x_next = (x_i + (n / x_i)) >>> 1;
  assign sqrt = x_i;
  assign sqrt_reg = sqrt;
  assign out_sqrt_reg = sqrt_reg;
  assign val_comb = n == 0 ? 1'b0 : x_next >= x_i ? 1'b1 : 1'b0;
  assign z_comb = n == 0 ? 1'b1 : 1'b0;
  always @(posedge CLK, posedge RST_n) begin
    if(RST_n == 1'b0) begin
      sqrt_reg <= {32{1'b0}};
      val_ff <= 1'b0;
      z_ff <= 1'b0;
    end else begin
      if(EN == 1'b1) begin
        sqrt_reg <= out_sqrt_reg;
        val_ff <= val_comb;
        z_ff <= z_comb;
      end
    end
  end
  assign out_sqrt = out_sqrt_reg;
  assign VAL = val_ff;
  assign Z = z_ff;
endmodule

module cycloneii_latch(D, ENA, PRE, CLR, Q);

   input D;
   input ENA, PRE, CLR;
   output Q;
