   wire D_in;
   wire ENA_in;
   wire PRE_in;
   wire CLR_in;

   buf (D_in, D);
   buf (ENA_in, ENA);
   buf (PRE_in, PRE);
   buf (CLR_in, CLR);

   specify
      (D => Q) = (0, 0);
      (ENA => Q) = (0, 0);
      (PRE => Q) = (0, 0);
      (CLR => Q) = (0, 0);
   endspecify

   initial
      q_out = 0;

   always @ (D_in or ENA_in or PRE_in or CLR_in)
   begin
      if (PRE_in == 1'b1)
         q_out <= 1;
      else if (CLR_in == 1'b1)
         q_out <= 0;
      else if ((ENA_in == 1'b1) && (D_in == 1'b1))
         q_out <= 1;
      else if ((ENA_in == 1'b1) && (D_in == 1'b0))
         q_out <= 0;
   end

   assign Q = q_out;

endmodule

