module barrel_shifter_tb;
reg [7:0] in;
	reg [2:0] shift;
	reg [7:0] out;
	reg [7:0] expected;
	reg [7:0] error;

	barrel_shifter shifter(in, shift, out);

	initial begin
		error = 0;
		in = 8'b10000000;
		shift = 3'b010;
		#1;
		expected = 8'b01000000;
		if (out != expected) begin
			$display("Error: Expected %b, got %b", expected, out);
			error = error + 1;
		end
		#1;
		in = 8'b11111111;
		shift = 3'b011;
		#1;
		expected = 8'b01111111;
		if (out != expected) begin
			$display("Error: Expected %b, got %b", expected, out);
			error = error + 1;
		end
		#1;
		in = 8'b10000000;
		shift = 3'b001;
		#1;
		expected = 8'b01000000;
		if (out != expected) begin
			$display("Error: Expected %b, got %b", expected, out);
			error = error + 1;
		end
		#1;
		in = 8'b11111111;
		shift = 3'b111;
		#1;
		expected = 8'b00000001;
		if (out != expected) begin
			$display("Error: Expected %b, got %b", expected, out);
			error = error + 1;
		end
		#1;
		if (error == 0) begin
			$display("All tests passed!");
		end
		$finish;
	end
endmodule

