module UART_rx(
input wire clk,
input wire reset,
input wire rx_data_in,
output reg [7:0] rx_data_out
); 

parameter [31:0] baud_rate=115200;
parameter [31:0] counter_max=16 * baud_rate;
parameter [31:0] counter_max_half=counter_max / 2;
parameter [31:0] counter_max_quarter=counter_max / 4;
parameter [31:0] counter_max_eighth=counter_max / 8;
parameter [31:0] counter_max_sixteenth=counter_max / 16;
parameter [31:0] counter_max_twentyfourth=counter_max / 24;
parameter [31:0] counter_max_thirtysecond=counter_max / 32;
parameter [31:0] counter_max_sixtyfourth=counter_max / 64;
parameter [31:0] counter_max_twentyfifth=counter_max / 25;
parameter [31:0] counter_max_twentyfifth_half=counter_max_twentyfifth / 2;
parameter [31:0] counter_max_twentyfifth_quarter=counter_max_twentyfifth / 4;
parameter [31:0] counter_max_twentyfifth_eighth=counter_max_twentyfifth / 8;
parameter [31:0] counter_max_twentyfifth_sixteenth=counter_max_twentyfifth / 16;
parameter [31:0] counter_max_twentyfifth_twentyfourth=counter_max_twentyfifth / 24;
parameter [31:0] counter_max_twentyfifth_thirtysecond=counter_max_twentyfifth / 32;
parameter [31:0] counter_max_twentyfifth_sixtyfourth=counter_max_twentyfifth / 64;
  parameter [31:0] IDLE=0;
  parameter [31:0] START=1;
  parameter [31:0] DATA=2;
  parameter [31:0] STOP=3;
  reg [31:0] counter = 0;
  reg [31:0] state = IDLE;
  reg [7:0] data = 1'b0;
  always @(posedge clk, posedge reset) begin
    if((reset == 1'b1)) begin
      counter <= 0;
      state <= IDLE;
      rx_data_out <= 8'b00000000;
    end else begin
      if((counter == counter_max)) begin
        counter <= 0;
        case(state)
        IDLE : begin
          if((rx_data_in == 1'b0)) begin
            state <= START;
            data <= 8'b00000000;
          end
        end
        START : begin
          if((counter == counter_max_quarter)) begin
            state <= DATA;
          end
        end
        DATA : begin
          if((counter == counter_max_quarter)) begin
            data[7 - (counter / counter_max_quarter)] <= rx_data_in;
          end
          if((counter == counter_max)) begin
            state <= STOP;
          end
        end
        STOP : begin
          if((counter == counter_max_quarter)) begin
            rx_data_out <= data;
            state <= IDLE;
          end
        end
        endcase
      end
      else begin
        counter <= counter + 1;
      end
    end
  end
endmodule

module serial(clk, reset, rxD,sout,signal,counter);
input clk;      
input reset;    
input rxD;   

output reg [n-1:0]sout; 
output reg signal;   
output reg [31:0]counter;
parameter n = 30; 
parameter count = 4; 
reg [1:0]delay; 
wire [7:0]s_in; 
top top1(clk, reset, rxD,s_in); 
always @(posedge clk or negedge reset) begin 
if(reset == 0) begin 
sout <= 0; 
signal <= 0; 
counter <= 0; 
delay <= 0; 
end 
else begin 
sout <= {s_in,sout[n-1:1]}; 
counter <= counter + 1; 
if(counter == count) begin 
delay <= 1; 
signal <= 1; 
counter <= 0; 
end 
else begin 
delay <= 0; 
signal <= 0; 
end 
end 
end 
endmodule

