module twocmp(input [31:0]A,output [31:0]B);
genvar i;
    generate
        for(i=0;i<32;i=i+1)
            if(i==0)
                assign B[i]=A[i];
            else
                assign B[i]=(|A[0:i-1])?~A[i]:A[i];
    endgenerate
endmodule

module arbiter (
clock, 
reset, 
req_0,
req_1, 
gnt_0,
gnt_1
);

input clock, reset, req_0, req_1;
output gnt_0, gnt_1;
reg gnt_0, gnt_1;

always @(posedge clock or posedge reset)
begin
	if (reset)
	begin
		gnt_0 <= 0;
		gnt_1 <= 0;
	end
	else
	begin
		if (req_0)
		begin
			gnt_0 <= 1;
			gnt_1 <= 0;
		end
		else if (req_1)
		begin
			gnt_0 <= 0;
			gnt_1 <= 1;
		end
		else
		begin
			gnt_0 <= 0;
			gnt_1 <= 0;
		end
	end
end

endmodule

module NAND3C(Y,A,B,C);
 input A,B,C;
 output Y;
not	INV_101(A_, A);
 not	INV_102(B_, B);
 not	INV_103(C_, C);
 and      U601(Y_, A_, B_);
 nand     U602(Y, Y_, C_);

       specify

		specparam tpdLH_A_to_Y = (0.1:0.1:0.1);
		specparam tpdHL_A_to_Y = (0.1:0.1:0.1);
		specparam tpdLH_B_to_Y = (0.1:0.1:0.1);
		specparam tpdHL_B_to_Y = (0.1:0.1:0.1);
		specparam tpdLH_C_to_Y = (0.1:0.1:0.1);
		specparam tpdHL_C_to_Y = (0.1:0.1:0.1);
		specparam MacroType = "comb";



		(A => Y ) = ( tpdLH_A_to_Y, tpdHL_A_to_Y );
		(B => Y ) = ( tpdLH_B_to_Y, tpdHL_B_to_Y );
		(C => Y ) = ( tpdLH_C_to_Y, tpdHL_C_to_Y );
   endspecify

endmodule

module th22i
    #(parameter INITIAL = 0) (
      input	 init,
      input	 A, 
      input	 B, 
      output reg Q);
always @* begin
	if (init)
	    Q <= #1 INITIAL;
	else if (A & B)
	    Q <= #INITIAL 1;
	else if (!A & !B)
	    Q <= #3+INITIAL 0;
    end
endmodule

