module zmc2_dot(
	input CLK_12M,
	input EVEN,
	input LOAD,
	input H,
	input [31:0] CR,
	output reg [3:0] GAD, GBD,
	output reg DOTA, DOTB
);
reg [31:0] SR;
	always @(negedge CLK_12M) begin
		if (LOAD)
			SR <= CR;
		else
			SR <= SR << 1;
	end
	always @(SR) begin
		if (H) begin
			GAD <= SR[31:28] | SR[27:24];
			GBD <= SR[23:20] | SR[19:16];
		end else begin
			GAD <= SR[31:28] | SR[27:24];
			GBD <= SR[23:20] | SR[19:16];
		end
		DOTA <= GAD[3] | GAD[2];
		DOTB <= GBD[3] | GBD[2];
	end
endmodule

