module Bin2BCDConverter_4
#(
	parameter INPUT_BIT_WIDTH  = 8
)
(
    input [(INPUT_BIT_WIDTH-1):0] Input,
    output reg [3:0] Digit3,
    output reg [3:0] Digit2,
    output reg [3:0] Digit1,
    output reg [3:0] Digit0
);
integer i;
    always @ (Input)
    begin
        Digit3 = 0;
        Digit2 = 0;
        Digit1 = 0;
        Digit0 = 0;
        for (i = (INPUT_BIT_WIDTH-1); i >= 0; i = i - 1)
        begin
            if (Digit3 >= 5)
                Digit3 = Digit3 + 4;
            if (Digit2 >= 5)
                Digit2 = Digit2 + 4;
            if (Digit1 >= 5)
                Digit1 = Digit1 + 4;
            if (Digit0 >= 5)
                Digit0 = Digit0 + 4;
            Digit3 = Digit3 << 1;
            Digit3[0] = Digit2[3];
            Digit2 = Digit2 << 1;
            Digit2[0] = Digit1[3];
            Digit1 = Digit1 << 1;
            Digit1[0] = Digit0[3];
            Digit0 = Digit0 << 1;
            Digit0[0] = Input[i];
        end
    end
endmodule

