module vga_sync(
input wire clk,
input wire rst,
output reg active,
output reg hsync,
output reg vsync,
output wire [9:0] xaddr,
output wire [9:0] yaddr
); 

parameter [31:0] H_RES=640;
parameter [31:0] V_RES=480;
parameter [31:0] H_FRONT=16;
parameter [31:0] H_BACK=48;
parameter [31:0] H_RETRACE=96;
parameter [31:0] V_FRONT=10;
parameter [31:0] V_BACK=33;
parameter [31:0] V_RETRACE=2;
reg [31:0] h_count_reg = 0;
reg [31:0] v_count_reg = 0;
  always @(posedge clk, posedge rst) begin
    if((rst == 1'b1)) begin
      h_count_reg <= 0;
      v_count_reg <= 0;
    end else begin
      if((h_count_reg == (H_RES + H_FRONT + H_BACK + H_RETRACE - 1))) begin
        h_count_reg <= 0;
        if((v_count_reg == (V_RES + V_FRONT + V_BACK + V_RETRACE - 1))) begin
          v_count_reg <= 0;
        end
        else begin
          v_count_reg <= v_count_reg + 1;
        end
      end
      else begin
        h_count_reg <= h_count_reg + 1;
      end
    end
  end
  always @(h_count_reg, v_count_reg) begin
    if((h_count_reg >= H_RES && h_count_reg < (H_RES + H_FRONT) && v_count_reg >= V_RES && v_count_reg < (V_RES + V_FRONT))) begin
      active <= 1'b1;
    end
    else begin
      active <= 1'b0;
    end
    if((h_count_reg >= (H_RES + H_FRONT) && h_count_reg < (H_RES + H_FRONT + H_RETRACE))) begin
      hsync <= 1'b0;
    end
    else begin
      hsync <= 1'b1;
    end
    if((v_count_reg >= (V_RES + V_FRONT) && v_count_reg < (V_RES + V_FRONT + V_RETRACE))) begin
      vsync <= 1'b0;
    end
    else begin
      vsync <= 1'b1;
    end
  end
  assign xaddr = h_count_reg;
  assign yaddr = v_count_reg;
endmodule

