module TopModule(in, state, next_state, out);
input in;
input [1:0] state;
output [1:0] next_state;
output out;
assign next_state = (state == 2'b00) ? (in ? 2'b01 : 2'b00) : 
					(state == 2'b01) ? (in ? 2'b11 : 2'b10) : 
					(state == 2'b10) ? (in ? 2'b00 : 2'b11) : 
					(state == 2'b11) ? (in ? 2'b10 : 2'b01) : 2'b00;
assign out = (state == 2'b00) ? 1'b0 : 
				(state == 2'b01) ? 1'b0 : 
				(state == 2'b10) ? 1'b0 : 
				(state == 2'b11) ? 1'b1 : 1'b0;
endmodule

