module TopModule(
    input clk,
    input reset,
    input in,
    output out
);
parameter A = 1'b0;
    parameter B = 1'b1;
    reg state;
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= B;
        end else begin
            case (state)
                A: begin
                    if (in) begin
                        state <= A;
                    end else begin
                        state <= B;
                    end
                end
                B: begin
                    if (in) begin
                        state <= B;
                    end else begin
                        state <= A;
                    end
                end
            endcase
        end
    end
    assign out = state;
endmodule

