module TopModule (
  input clk,
  input reset,
  output [3:1] ena,
  output reg [15:0] q
);
wire [3:0] ones = q[3:0];
  wire [3:0] tens = q[7:4];
  wire [3:0] hundreds = q[11:8];
  wire [3:0] thousands = q[15:12];

  wire [3:1] ones_ena = {1'b0, ones[3:1]};
  wire [3:1] tens_ena = {1'b0, tens[3:1]};
  wire [3:1] hundreds_ena = {1'b0, hundreds[3:1]};
  wire [3:1] thousands_ena = {1'b0, thousands[3:1]};

  always @(posedge clk) begin
    if (reset) begin
      q <= 16'b0;
    end else begin
      if (ones >= 4'd9) begin
        q[3:0] <= ones + 4'd6;
        if (tens >= 4'd9) begin
          q[7:4] <= tens + 4'd6;
          if (hundreds >= 4'd9) begin
            q[11:8] <= hundreds + 4'd6;
            if (thousands >= 4'd9) begin
              q[15:12] <= thousands + 4'd6;
            end
          end
        end
      end
      q[3:0] <= ones + 4'd1;
      q[7:4] <= tens + 4'd1;
      q[11:8] <= hundreds + 4'd1;
      q[15:12] <= thousands + 4'd1;
    end
  end

  assign ena = {ones_ena, tens_ena, hundreds_ena, thousands_ena};

endmodule

