module TopModule (
  input in,
  input [3:0] state,
  output reg [3:0] next_state,
  output out
);
always @* begin
    case (state)
      4'b0001: begin
        next_state = in ? 4'b0010 : 4'b0100;
        out = 1'b0;
      end
      4'b0010: begin
        next_state = in ? 4'b0100 : 4'b1000;
        out = 1'b0;
      end
      4'b0100: begin
        next_state = in ? 4'b0001 : 4'b1000;
        out = 1'b0;
      end
      4'b1000: begin
        next_state = in ? 4'b0100 : 4'b0010;
        out = 1'b1;
      end
      default: begin
        next_state = 4'b0000;
        out = 1'bx;
      end
    endcase
  end
endmodule

