module TopModule (
  input clk,
  input aresetn,
  input x,
  output reg z
);
reg [1:0] state;

  always @(posedge clk or negedge aresetn) begin
    if (!aresetn) begin
      state <= 2'b00;
      z <= 1'b0;
    end else begin
      case (state)
        2'b00: begin
          if (x == 1'b1) begin
            state <= 2'b01;
            z <= 1'b0;
          end else begin
            state <= 2'b00;
            z <= 1'b0;
          end
        end
        2'b01: begin
          if (x == 1'b0) begin
            state <= 2'b10;
            z <= 1'b0;
          end else begin
            state <= 2'b00;
            z <= 1'b0;
          end
        end
        2'b10: begin
          if (x == 1'b1) begin
            state <= 2'b11;
            z <= 1'b1;
          end else begin
            state <= 2'b00;
            z <= 1'b0;
          end
        end
        2'b11: begin
          if (x == 1'b0) begin
            state <= 2'b00;
            z <= 1'b0;
          end else begin
            state <= 2'b01;
            z <= 1'b0;
          end
        end
        default: begin
          state <= 2'b00;
          z <= 1'b0;
        end
      endcase
    end
  end

endmodule

module TopModule (
  input [3:0] a,
  input [3:0] b,
  input [3:0] c,
  input [3:0] d,
  input [3:0] e,
  output reg [3:0] q
);
always @* begin
    case (c)
      0: q = b;
      1: q = e;
      2: q = a;
      3: q = d;
      4: q = f;
      default: q = f;
    endcase
  end
endmodule

module TopModule (
