A A1 (x, y, z1);
  A A2 (x, y, z2);
  B B1 (x, y, z1);
  B B2 (x, y, z2);
  or (z1, z1, z2);
  and (z2, z1, z2);
  xor (z, z1, z2);
endmodule

module TopModule (
  input cpu_overheated,
  output reg shut_off_computer,
  input arrived,
  input gas_tank_empty,
  output reg keep_driving
);
always @(*) begin
    if (cpu_overheated)
      shut_off_computer = 1;
  end

  always @(*) begin
    if (~arrived)
      keep_driving = ~gas_tank_empty;
  end

endmodule

module TopModule (
  input clk,
  input reset,
  input s,
  input w,
  output reg z
);
parameter A = 2'b00;
  parameter B = 2'b01;
  parameter C = 2'b10;
  parameter D = 2'b11;
  reg [1:0] state;
  always @(posedge clk) begin
    if (reset) begin
      state <= A;
    end else begin
      case (state)
        A: begin
          if (s) begin
            state <= B;
          end
        end
        B: begin
          if (w) begin
            state <= C;
          end
        end
        C: begin
          if (w) begin
            state <= D;
          end
        end
        D: begin
          if (w) begin
            z <= 1;
          end else begin
            z <= 0;
          end
          state <= A;
        end
      endcase
    end
  end
endmodule

module TopModule (
  input clk,
  input x,
  input [2:0] y,
  output reg Y0,
  output reg z
);
reg [2:0] Y;
  always @(posedge clk) begin
    Y <= (x == 0) ? Y : (x == 1) ? Y : 0;
    Y0 <= Y[0];
    z <= Y[1];
  end
endmodule

module TopModule (
  input [2:0] y,
  input w,
  output reg Y1
);
always @* begin
    case (y)
      3'b000: Y1 = 1'b0;
      3'b001: Y1 = 1'b0;
      3'b010: Y1 = 1'b0;
      3'b011: Y1 = 1'b1;
      3'b100: Y1 = 1'b0;
      3'b101: Y1 = 1'b1;
      default: Y1 = 1'bx;
    endcase
  end
endmodule

