module TopModule (
  input clk,
  input areset,
  input bump_left,
  input bump_right,
  input ground,
  output walk_left,
  output walk_right,
  output aaah
);
reg walk_left_reg;
  reg walk_right_reg;
  reg aaah_reg;
  always @(posedge clk) begin
    if (areset) begin
      walk_left_reg <= 1;
      walk_right_reg <= 0;
      aaah_reg <= 0;
    end
    else begin
      if (ground == 0) begin
        walk_left_reg <= 0;
        walk_right_reg <= 0;
        aaah_reg <= 1;
      end
      else begin
        if (walk_left_reg) begin
          if (bump_left) begin
            walk_left_reg <= 0;
            walk_right_reg <= 1;
          end
          else begin
            walk_left_reg <= 1;
            walk_right_reg <= 0;
          end
        end
        else begin
          if (bump_right) begin
            walk_left_reg <= 1;
            walk_right_reg <= 0;
          end
          else begin
            walk_left_reg <= 0;
            walk_right_reg <= 1;
          end
        end
        aaah_reg <= 0;
      end
    end
  end
  assign walk_left = walk_left_reg;
  assign walk_right = walk_right_reg;
  assign aaah = aaah_reg;
endmodule

