module TopModule (
  input clk,
  input load,
  input [255:0] data,
  output reg [255:0] q
);
always @(posedge clk) begin
    if (load) begin
      q <= data;
    end else begin
      q <= q + 1;
    end
  end

  always @(posedge clk) begin
    for (int i = 0; i < 256; i = i + 1) begin
      int x = i % 16;
      int y = i / 16;
      int count = 0;
      for (int dx = -1; dx <= 1; dx = dx + 1) begin
        for (int dy = -1; dy <= 1; dy = dy + 1) begin
          if (dx == 0 && dy == 0) begin
            continue;
          end
          int nx = (x + dx) % 16;
          int ny = (y + dy) % 16;
          count = count + q[ny * 16 + nx];
        end
      end
      if (count == 0 || count == 1) begin
        q[i] <= 0;
      end else if (count == 2) begin
        q[i] <= q[i];
      end else if (count == 3) begin
        q[i] <= 1;
      end else begin
        q[i] <= 0;
      end
    end
  end

endmodule

