module TopModule (
  input clk,
  input resetn,
  input  [2:0] r,
  output [2:0] g
);
reg [1:0] state, next_state;

  always @(posedge clk or negedge resetn) begin
    if (!resetn) begin
      state <= 0;
    end else begin
      state <= next_state;
    end
  end

  always @(*) begin
    case (state)
      0: begin
        if (r[0] == 0 && r[1] == 0 && r[2] == 0) begin
          next_state = 0;
        end else if (r[0] == 1) begin
          next_state = 1;
        end else if (r[0] == 0 && r[1] == 1) begin
          next_state = 2;
        end else if (r[0] == 0 && r[1] == 0 && r[2] == 1) begin
          next_state = 3;
        end else begin
          next_state = 0;
        end
      end
      1: begin
        if (r[0] == 1) begin
          next_state = 1;
        end else begin
          next_state = 0;
        end
      end
      2: begin
        if (r[1] == 1) begin
          next_state = 2;
        end else begin
          next_state = 0;
        end
      end
      3: begin
        if (r[2] == 1) begin
          next_state = 3;
        end else begin
          next_state = 0;
        end
      end
      default: begin
        next_state = 0;
      end
    endcase
  end

  assign g = (state == 1) ? 3'b100 : (state == 2) ? 3'b010 : (state == 3) ? 3'b001 : 3'b000;

endmodule

