          end
        end else begin
          if (bump_right == 1) begin
            walk_left_reg <= 1;
          end
        end
      end
    end
  end
  assign walk_left = walk_left_reg;
  assign walk_right = ~walk_left_reg;
  assign aaah = aaah_reg;
  assign digging = digging_reg;
endmodule

module TopModule (
  input clk,
  input areset,

  input predict_valid,
  input [6:0] predict_pc,
  output predict_taken,
  output [6:0] predict_history,

  input train_valid,
  input train_taken,
  input train_mispredicted,
  input [6:0] train_history,
  input [6:0] train_pc
);
wire [6:0] index = predict_pc ^ predict_history;
  wire [6:0] index2 = train_pc ^ train_history;

  reg [6:0] branch_history = 7'b0;
  wire [6:0] branch_history_next = branch_history ^ {index[6:0], predict_taken};

  reg [1:0] pht [127:0];
  wire [1:0] pht_next [127:0];
  wire [1:0] pht_next2 [127:0];

  assign pht_next = pht;
  assign pht_next2 = pht;

  assign predict_taken = pht[index];
  assign predict_history = branch_history;

  assign pht_next[index] = pht[index] + (predict_taken ? 1'b0 : 1'b1);
  assign pht_next2[index2] = pht[index2] + (train_taken ? 1'b0 : 1'b1);

  always @(posedge clk) begin
    if (predict_valid) begin
      branch_history <= branch_history_next;
    end
    if (train_valid) begin
      pht[index2] <= pht_next2[index2];
      if (train_mispredicted) begin
        branch_history <= branch_history_next;
      end
    end
  end

endmodule

